LOCALIZED_QUESTION_BANKS={"en": {"\u20ac100": [{"question": "What does ESA stand for?", "answers": ["European Science Alliance", "European Satellite Agency", "European Space Agency", "Europe Space Association"], "correct": 2, "fact": "ESA brings European countries together to explore space and use space technology for the benefit of people on Earth."}, {"question": "Among other what does ESA primarily study and explore?", "answers": ["The oceans", "Space and Earth from space", "Earth's underground", "All of the above"], "correct": 3, "fact": "ESA develops and operates Space missions that study Earth, including its underground composition and interior strictures, the Solar System and the wider Universe."}, {"question": "What is the main purpose of ESA?", "answers": ["To promote Space research, technology and applications", "To build airplanes", "To operate airports", "To provide weather forecasts"], "correct": 0, "fact": "ESA's purpose shall be to provide for, and to promote, for exclusively peaceful purposes, cooperation among European States in space research and technology"}, {"question": "What is ESA?", "answers": ["A university", "A European organization", "A private company", "An airline"], "correct": 1, "fact": "ESA stands for European Space Agency, an international organization dedicated to shape the development of Europe\u2019s Space capability and ensure that investment in space continues to deliver benefits to the citizens of Europe and the world."}, {"question": "Does ESA work with astronauts?", "answers": ["Yes, with ESA astronauts", "No, but it works with Pilots", "Yes, but only with NASA astronauts", "No, it works only with Scientists on Earth"], "correct": 0, "fact": "ESA trains and maintains a Team of Astronauts coming from different European coutries to explore Space."}, {"question": "Which is an area of ESA's work?", "answers": ["Space technology", "Fascion design", "Food production", "Road transport"], "correct": 0, "fact": "ESA's purpose shall be to provide for, and to promote, for exclusively peaceful purposes, cooperation among European States in space research and technology"}], "\u20ac200": [{"question": "Which planet is known as the \u2018Red Planet\u2019?", "answers": ["Venus", "Mars", "Jupiter", "Mercury"], "correct": 1, "fact": "Mars looks reddish because iron minerals in its soil have oxidised, a process rather like rusting."}, {"question": "Which planet is the largest in our Solar System?", "answers": ["Earth", "Saturn", "Jupiter", "Neptune"], "correct": 2, "fact": "Jupiter is the largest planet in the Solar System, with a diameter more than 11 times that of Earth."}, {"question": "Which planet is famous for its prominent ring system?", "answers": ["Mars", "Saturn", "Venus", "Mercury"], "correct": 1, "fact": "Saturn's rings are made mainly of countless pieces of ice and rocky material."}, {"question": "Which planet is closest to the Sun?", "answers": ["Venus", "Earth", "Mercury", "Mars"], "correct": 2, "fact": "Mercury is the innermost planet and completes an orbit around the Sun in about 88 Earth days."}, {"question": "Which planet is sometimes called Earth's sister planet because of its similar size?", "answers": ["Jupiter", "Venus", "Mars", "Neptune"], "correct": 1, "fact": "Venus is similar to Earth in size and composition, although its surface environment is extremely different."}, {"question": "What is the name of the galaxy containing our Solar System?", "answers": ["Andromeda", "The Milky Way", "Whirlpool", "Sombrero"], "correct": 1, "fact": "Our Solar System is located in the Milky Way, a barred spiral galaxy containing hundreds of billions of stars."}], "\u20ac500": [{"question": "What are Earth-observation satellites mainly used for?", "answers": ["Weather forecasting only", "Monitoring Earth and environmental change", "Broadcasting television only", "Taking holiday photographs"], "correct": 1, "fact": "Satellite data can help monitor forests, sea ice, air quality, floods, fires, crops and many other changes on our planet."}, {"question": "What can satellites help scientists monitor over large areas?", "answers": ["Forest changes", "Only individual houses", "Only underground caves", "Nothing on Earth's surface"], "correct": 0, "fact": "Earth-observation satellites can repeatedly survey large areas, helping track changes in forests, agriculture and ecosystems."}, {"question": "Why are satellites useful for observing remote parts of Earth?", "answers": ["They can observe large areas from orbit", "They never need instruments", "They only work over cities", "They replace all ground measurements"], "correct": 0, "fact": "Satellites can provide repeated observations of places that are difficult or dangerous to reach from the ground."}, {"question": "Which event can Earth-observation satellites help monitor?", "answers": ["Flooding", "Only solar eclipses", "Only meteor showers", "Only spacecraft launches"], "correct": 0, "fact": "Satellite observations can help map flooded areas and support monitoring before, during and after major floods."}, {"question": "Which of these can satellite observations help monitor in the ocean?", "answers": ["Sea-ice extent", "Only fish inside individual nets", "Only ships at harbours", "Nothing"], "correct": 0, "fact": "Satellite observations can track sea ice and many other large-scale ocean and coastal changes."}, {"question": "What is one advantage of observing Earth from space?", "answers": ["Global or regional coverage", "No data processing is needed", "Clouds can never affect observations", "Every satellite sees everything"], "correct": 0, "fact": "Different satellite instruments provide broad coverage and repeated measurements that complement observations made from the ground."}], "\u20ac1,200": [{"question": "What is the name of the European family of Earth-observation missions used by the Copernicus programme?", "answers": ["Galileo", "Sentinel", "Voyager", "Kepler"], "correct": 1, "fact": "The Sentinel missions act like different sets of eyes. Some use radar, while others observe land, oceans or the atmosphere."}, {"question": "Which Copernicus Sentinel mission uses radar to observe Earth?", "answers": ["Sentinel-1", "Sentinel-6", "Sentinel-5P", "Sentinel-2"], "correct": 0, "fact": "Sentinel-1 uses radar, allowing it to observe Earth's surface day and night and through cloud cover."}, {"question": "Which Sentinel mission is particularly associated with detailed land-surface imagery?", "answers": ["Sentinel-2", "Sentinel-3", "Sentinel-5P", "Sentinel-6"], "correct": 0, "fact": "Sentinel-2 provides high-resolution optical imagery useful for studying vegetation, land cover and many other surface features."}, {"question": "What is Copernicus?", "answers": ["Europe's Earth-observation programme", "A Mars rover", "A type of rocket engine", "A star catalogue"], "correct": 0, "fact": "Copernicus is the European Union's Earth-observation programme, using satellites and other sources to provide environmental information."}, {"question": "Why can radar satellites be useful during cloudy weather?", "answers": ["Radar can observe through clouds in many situations", "Radar turns clouds into clear skies", "Radar only works indoors", "Radar cannot detect Earth's surface"], "correct": 0, "fact": "Synthetic-aperture radar can collect useful observations regardless of daylight and can often see through cloud cover."}, {"question": "Which type of information can Sentinel missions provide?", "answers": ["Land, ocean and atmosphere observations", "Only photographs of astronauts", "Only radio broadcasts", "Only observations of the Moon"], "correct": 0, "fact": "Different Sentinel missions are designed for different environmental measurements, covering land, oceans and the atmosphere."}], "\u20ac2,000": [{"question": "Which ESA mission placed the Philae lander on a comet in 2014?", "answers": ["Gaia", "Rosetta", "Euclid", "Solar Orbiter"], "correct": 1, "fact": "Philae bounced after its first touchdown on Comet 67P. In the comet\u2019s extremely weak gravity, even a gentle bounce became a dramatic journey."}, {"question": "What was the name of the comet visited by ESA's Rosetta mission?", "answers": ["Halley", "67P/Churyumov-Gerasimenko", "Hale-Bopp", "Shoemaker-Levy 9"], "correct": 1, "fact": "Rosetta travelled to and studied Comet 67P/Churyumov-Gerasimenko, orbiting it for more than two years."}, {"question": "What was Philae?", "answers": ["A lander", "A telescope", "A rocket", "A communications satellite"], "correct": 0, "fact": "Philae was a small robotic lander carried to Comet 67P by ESA's Rosetta spacecraft."}, {"question": "What makes landing on a small comet especially challenging?", "answers": ["Very weak gravity", "Too much oxygen", "A thick atmosphere", "Strong ocean currents"], "correct": 0, "fact": "A small comet has extremely weak gravity, making it difficult for a lander to stay attached to the surface."}, {"question": "How many ESA Astonauts went to Space from September 2021 to September 2026?", "answers": ["6", "20", "1", "None"], "correct": 0, "fact": "From the foundation of ESA, a total of 27 individual astronauts have traveled into space from different European Countries."}, {"question": "What was a major scientific goal of Rosetta?", "answers": ["To study a comet in detail", "To land humans on Mars", "To map Earth's oceans", "To observe the Sun's poles"], "correct": 0, "fact": "Rosetta studied the composition, structure and activity of Comet 67P to improve our understanding of comets and the early Solar System."}], "\u20ac4,000": [{"question": "ESA\u2019s Gaia mission was designed to create an extraordinarily precise map of what?", "answers": ["Earth\u2019s oceans", "The Moon\u2019s craters", "The Milky Way galaxy", "Mars\u2019s volcanoes"], "correct": 2, "fact": "By measuring the positions and motions of stars, Gaia helps astronomers investigate the history and structure of our galaxy."}, {"question": "What does Gaia measure very precisely for stars?", "answers": ["Positions and motions", "Their smell", "Their surface temperature only", "Their weather forecasts"], "correct": 0, "fact": "Gaia's astrometric measurements reveal how stars are positioned and moving through the Milky Way."}, {"question": "Which kind of object is Gaia primarily surveying?", "answers": ["Stars", "Volcanoes", "Clouds", "Oceans"], "correct": 0, "fact": "Gaia was designed to survey enormous numbers of stars and build a precise three-dimensional picture of the Milky Way."}, {"question": "Why are stellar motions useful to astronomers?", "answers": ["They reveal information about the Milky Way's structure and history", "They predict Earth's weather", "They control spacecraft directly", "They create new stars"], "correct": 0, "fact": "The positions and motions of stars contain clues about how our galaxy formed and evolved."}, {"question": "Which part of the electromagnetic spectrum does Gaia use for its main astrometric measurements?", "answers": ["Visible light", "Radio only", "X-rays only", "Gamma rays only"], "correct": 0, "fact": "Gaia operates primarily as an optical astrometry mission, measuring stellar positions and motions with extraordinary precision."}, {"question": "What can a detailed map of the Milky Way help scientists investigate?", "answers": ["The galaxy's formation and evolution", "The exact weather tomorrow", "Ocean tides on Jupiter", "The colour of Earth's clouds"], "correct": 0, "fact": "A precise stellar map helps researchers reconstruct the structure, dynamics and history of our galaxy."}], "\u20ac8,000": [{"question": "Which ESA-led mission studies the Sun and is designed to observe its polar regions?", "answers": ["Solar Orbiter", "JUICE", "Hera", "BepiColombo"], "correct": 0, "fact": "The Sun\u2019s poles are difficult to see from Earth. Solar Orbiter uses planetary flybys to tilt its orbit and obtain a better view."}, {"question": "What is Solar Orbiter designed to study?", "answers": ["The Sun", "Jupiter's moons", "Comets only", "Earth's glaciers only"], "correct": 0, "fact": "Solar Orbiter studies the Sun and the solar wind, helping scientists understand how our star works."}, {"question": "Why does Solar Orbiter use planetary flybys?", "answers": ["To change and tilt its orbit", "To refuel with sunlight", "To land on a planet", "To collect rocks from Earth"], "correct": 0, "fact": "Gravity assists from planets can change a spacecraft's trajectory and help Solar Orbiter obtain a higher-inclination orbit."}, {"question": "What is the solar wind?", "answers": ["A flow of charged particles from the Sun", "Wind in Earth's atmosphere", "A stream of water on Mars", "A ring around Saturn"], "correct": 0, "fact": "The solar wind is a continuous flow of charged particles escaping from the Sun's outer atmosphere."}, {"question": "Which feature of the Sun is especially important for understanding its magnetic activity?", "answers": ["Its magnetic field", "Its rings", "Its oceans", "Its solid surface"], "correct": 0, "fact": "The Sun's magnetic field drives many forms of solar activity, including sunspots and solar eruptions."}, {"question": "What makes observing the Sun's polar regions from Earth difficult?", "answers": ["The viewing geometry", "The Moon blocks them every day", "The Sun has no poles", "They are behind Saturn"], "correct": 0, "fact": "From Earth's usual viewpoint, the Sun's poles are seen at a very shallow angle, so a spacecraft with a tilted orbit can provide a valuable new perspective."}], "\u20ac16,000": [{"question": "What can Copernicus Sentinel satellites detect in Antarctica?", "answers": ["Dinosaurs walking under the ice", "Changes in the thickness and movement of ice", "Alien radio messages", "Volcanoes on Mars"], "correct": 1, "fact": "Radar satellites can observe ice even through clouds and during the long polar night, making them valuable tools for tracking change."}, {"question": "Why is radar particularly useful for observing Antarctica?", "answers": ["It can operate without sunlight and through cloud cover", "It melts the ice", "It only works at noon", "It needs clear skies at all times"], "correct": 0, "fact": "Radar instruments can collect observations in darkness and are much less dependent on cloud-free conditions than optical instruments."}, {"question": "What can satellite observations reveal about glaciers?", "answers": ["Changes in their movement", "Their taste", "Their exact age of every snowflake", "Their internal temperature everywhere"], "correct": 0, "fact": "Repeated satellite observations can show how quickly glaciers and ice streams move and how those patterns change over time."}, {"question": "What is an ice sheet?", "answers": ["A vast mass of land ice covering a large area", "A layer of sea water", "A cloud formation", "A volcanic lava flow"], "correct": 0, "fact": "The Antarctic and Greenland ice sheets are enormous masses of land-based ice that contain most of 's freshwater ice."}, {"question": "What kind of change can satellite radar detect on an ice surface?", "answers": ["Movement and deformation", "Only colour", "Only air temperature", "Only the age of the ice"], "correct": 0, "fact": "Radar measurements can be used to detect surface movement and deformation, including changes in glaciers and ice sheets."}, {"question": "Why is monitoring Antarctic ice important to Earth science?", "answers": ["It helps track changes in the polar environment", "It determines the number of stars in the Milky Way", "It measures Jupiter's atmosphere", "It replaces all climate models"], "correct": 0, "fact": "Long-term observations of Antarctic ice help scientists understand changes in the polar environment and their wider effects."}], "\u20ac24,000": [{"question": "What does the name JUICE stand for?", "answers": ["Jupiter Investigation of Comets and Exploration", "Joint Universe Ice and Climate Explorer", "Jupiter Icy Moons Explorer", "Journey Into Cosmic Evolution"], "correct": 2, "fact": "JUICE is travelling to the Jupiter system to study the giant planet and its ocean-bearing icy moons."}, {"question": "Which planet is JUICE travelling to study?", "answers": ["Mars", "Jupiter", "Saturn", "Venus"], "correct": 1, "fact": "JUICE is ESA's Jupiter Icy Moons Explorer and is designed to investigate Jupiter and several of its large icy moons."}, {"question": "Which of these is one of the icy moons studied by JUICE?", "answers": ["Ganymede", "Phobos", "Titan", "Triton"], "correct": 0, "fact": "JUICE will study Ganymede in detail and also make observations of Europa and Callisto during its mission."}, {"question": "What is especially interesting about Jupiter's icy moons?", "answers": ["Some may contain subsurface oceans", "They all have Earth's atmosphere", "They are hotter than the Sun", "They are made entirely of metal"], "correct": 0, "fact": "Evidence indicates that some of Jupiter's icy moons contain oceans beneath their frozen surfaces."}, {"question": "Which moon is planned to become the main target of JUICE's orbital mission?", "answers": ["Ganymede", "Io", "Europa", "Amalthea"], "correct": 0, "fact": "JUICE is planned to enter orbit around Ganymede, making it the first spacecraft to orbit a moon other than Earth's Moon."}, {"question": "Why are icy moons interesting in the search for potentially habitable environments?", "answers": ["They may have liquid water beneath their ice", "They are all close to the Sun", "They have Earth's continents", "They are made of pure oxygen"], "correct": 0, "fact": "Liquid water is one of the ingredients scientists consider important when studying environments that might support some form of life."}], "\u20ac44,000": [{"question": "Which ESA-JAXA mission uses a complex series of planetary flybys on its journey to Mercury?", "answers": ["Euclid", "Sentinel-2", "BepiColombo", "Philae"], "correct": 2, "fact": "Getting to Mercury is surprisingly difficult. A spacecraft must lose a great deal of orbital energy, so BepiColombo uses flybys as carefully planned cosmic steering manoeuvres."}, {"question": "Which planet is the main destination of BepiColombo?", "answers": ["Mercury", "Mars", "Jupiter", "Venus"], "correct": 0, "fact": "BepiColombo is a joint ESA-JAXA mission designed to study Mercury, the innermost planet of the Solar System."}, {"question": "Why is reaching Mercury particularly challenging for a spacecraft from Earth?", "answers": ["It must lose orbital energy to fall closer to the Sun", "Mercury has a thick atmosphere", "Mercury is outside the Solar System", "It has oceans that block spacecraft"], "correct": 0, "fact": "A spacecraft travelling from Earth has to shed substantial orbital energy to enter an orbit close to the Sun, making Mercury a demanding destination."}, {"question": "When was ESA founded?", "answers": ["1975", "1965", "1970", "1985"], "correct": 0, "fact": "JAXA is Japan's national space agency and research organisation. BepiColombo is a collaboration between JAXA and ESA."}, {"question": "Where are the headquarters of ESA?", "answers": ["Paris, France", "Berlin, Germany", "Rome, Italy", "London, UK"], "correct": 0, "fact": "ESA has 23 member states and seven main estabilishment in Europe, with its headquarters being in the centre of Paris."}, {"question": "What is the biggest estabilishment of ESA?", "answers": ["ESRIN, Italy", "ESTEC, the Netherlands", "ESOC, Germany", "ESA Headquarters, France"], "correct": 1, "fact": "ESTEC is the European Space Research and Technology Centre, ESA's technical heart, where most ESA projects are born and where they are guided through the various phases of development."}]}, "it": {"\u20ac100": [{"question": "Qual \u00e8 l'acronimo di ESA?", "answers": ["Alleanza Scientifica Europea", "Agenzia Satellitare Europea", "Agenzia Spaziale Europea", "Associazione Spaziale Europea"], "correct": 2, "fact": "ESA riunisce i Paesi europei per esplorare lo spazio e utilizzare la tecnologia spaziale a beneficio delle persone sulla Terra."}, {"question": "Tra le altre cose, che cosa studia ed esplora principalmente l'ESA?", "answers": ["Gli oceani", "Lo spazio e la Terra dallo spazio", "Il sottosuolo della Terra", "Tutto quanto sopra"], "correct": 3, "fact": "ESA sviluppa e gestisce missioni spaziali che studiano la Terra, inclusi la composizione e la struttura del suo sottosuolo e del suo interno, il Sistema Solare e l'Universo pi\u00f9 vasto."}, {"question": "Qual \u00e8 lo scopo principale dell'ESA?", "answers": ["Promuovere la ricerca, la tecnologia e le applicazioni spaziali", "Costruire aeroplani", "Gestire gli aeroporti", "Fornire previsioni meteorologiche"], "correct": 0, "fact": "Lo scopo dell'ESA \u00e8 provvedere e promuovere, per finalit\u00e0 esclusivamente pacifiche, la cooperazione tra gli Stati europei nella ricerca e nella tecnologia spaziale."}, {"question": "Che cos'\u00e8 l'ESA?", "answers": ["Un'universit\u00e0", "Un'organizzazione europea", "Un'azienda privata", "Una compagnia aerea"], "correct": 1, "fact": "ESA \u00e8 l'acronimo di Agenzia Spaziale Europea, un'organizzazione internazionale dedicata a dare forma allo sviluppo delle capacit\u00e0 spaziali dell'Europa e a garantire che gli investimenti nello spazio continuino a portare benefici ai cittadini europei e al mondo."}, {"question": "L'ESA lavora con gli astronauti?", "answers": ["S\u00ec, con gli astronauti dell'ESA", "No, ma lavora con i piloti", "S\u00ec, ma solo con gli astronauti della NASA", "No, lavora solo con gli scienziati sulla Terra"], "correct": 0, "fact": "ESA addestra e mantiene una squadra di astronauti provenienti da diversi Paesi europei per esplorare lo spazio."}, {"question": "Quale di queste \u00e8 un'area di attivit\u00e0 dell'ESA?", "answers": ["Tecnologia spaziale", "Design della moda", "Produzione alimentare", "Trasporto stradale"], "correct": 0, "fact": "Lo scopo dell'ESA \u00e8 provvedere e promuovere, per finalit\u00e0 esclusivamente pacifiche, la cooperazione tra gli Stati europei nella ricerca e nella tecnologia spaziale."}], "\u20ac200": [{"question": "Quale pianeta \u00e8 noto come il \u00abPianeta Rosso\u00bb?", "answers": ["Venere", "Marte", "Giove", "Mercurio"], "correct": 1, "fact": "Marte appare rossastro perch\u00e9 i minerali di ferro nel suo suolo si sono ossidati, in un processo simile alla formazione della ruggine."}, {"question": "Quale pianeta \u00e8 il pi\u00f9 grande del nostro Sistema Solare?", "answers": ["Terra", "Saturno", "Giove", "Nettuno"], "correct": 2, "fact": "Giove \u00e8 il pianeta pi\u00f9 grande del Sistema Solare, con un diametro pi\u00f9 di 11 volte quello della Terra."}, {"question": "Quale pianeta \u00e8 famoso per il suo evidente sistema di anelli?", "answers": ["Marte", "Saturno", "Venere", "Mercurio"], "correct": 1, "fact": "Gli anelli di Saturno sono costituiti principalmente da innumerevoli frammenti di ghiaccio e materiale roccioso."}, {"question": "Quale pianeta \u00e8 pi\u00f9 vicino al Sole?", "answers": ["Venere", "Terra", "Mercurio", "Marte"], "correct": 2, "fact": "Mercurio \u00e8 il pianeta pi\u00f9 interno e completa un'orbita intorno al Sole in circa 88 giorni terrestri."}, {"question": "Quale pianeta \u00e8 talvolta chiamato il pianeta gemello della Terra per le sue dimensioni simili?", "answers": ["Giove", "Venere", "Marte", "Nettuno"], "correct": 1, "fact": "Venere \u00e8 simile alla Terra per dimensioni e composizione, anche se l'ambiente sulla sua superficie \u00e8 estremamente diverso."}, {"question": "Qual \u00e8 il nome della galassia che contiene il nostro Sistema Solare?", "answers": ["Andromeda", "La Via Lattea", "Vortice", "Sombrero"], "correct": 1, "fact": "Il nostro Sistema Solare si trova nella Via Lattea, una galassia a spirale barrata che contiene centinaia di miliardi di stelle."}], "\u20ac500": [{"question": "A cosa servono principalmente i satelliti per l'osservazione della Terra?", "answers": ["Solo per le previsioni meteorologiche", "Per monitorare la Terra e i cambiamenti ambientali", "Solo per trasmettere programmi televisivi", "Per scattare fotografie durante le vacanze"], "correct": 1, "fact": "I dati satellitari possono aiutare a monitorare foreste, ghiaccio marino, qualit\u00e0 dell'aria, inondazioni, incendi, colture e molti altri cambiamenti sul nostro pianeta."}, {"question": "Che cosa possono aiutare gli scienziati a monitorare i satelliti su vaste aree?", "answers": ["I cambiamenti nelle foreste", "Solo singole abitazioni", "Solo grotte sotterranee", "Nulla sulla superficie terrestre"], "correct": 0, "fact": "I satelliti per l'osservazione della Terra possono rilevare ripetutamente vaste aree, aiutando a monitorare i cambiamenti nelle foreste, nell'agricoltura e negli ecosistemi."}, {"question": "Perch\u00e9 i satelliti sono utili per osservare le zone remote della Terra?", "answers": ["Possono osservare vaste aree dall'orbita", "Non hanno mai bisogno di strumenti", "Funzionano solo sopra le citt\u00e0", "Sostituiscono tutte le misurazioni a terra"], "correct": 0, "fact": "I satelliti possono fornire osservazioni ripetute di luoghi difficili o pericolosi da raggiungere da terra."}, {"question": "Quale evento possono aiutare a monitorare i satelliti per l'osservazione della Terra?", "answers": ["Le inondazioni", "Solo le eclissi solari", "Solo gli sciami meteorici", "Solo i lanci di veicoli spaziali"], "correct": 0, "fact": "Le osservazioni satellitari possono aiutare a mappare le aree allagate e a supportare il monitoraggio prima, durante e dopo le grandi inondazioni."}, {"question": "Che cosa possono aiutare a monitorare le osservazioni satellitari nell'oceano?", "answers": ["L'estensione del ghiaccio marino", "Solo i pesci all'interno di singole reti", "Solo le navi nei porti", "Nulla"], "correct": 0, "fact": "Le osservazioni satellitari possono monitorare il ghiaccio marino e molti altri cambiamenti su larga scala negli oceani e nelle zone costiere."}, {"question": "Qual \u00e8 un vantaggio dell'osservazione della Terra dallo spazio?", "answers": ["Copertura globale o regionale", "Non \u00e8 necessaria alcuna elaborazione dei dati", "Le nuvole non possono mai influenzare le osservazioni", "Ogni satellite vede tutto"], "correct": 0, "fact": "Diversi strumenti satellitari forniscono un'ampia copertura e misurazioni ripetute che completano le osservazioni effettuate da terra."}], "\u20ac1,200": [{"question": "Qual \u00e8 il nome della famiglia europea di missioni per l'osservazione della Terra utilizzata dal programma Copernicus?", "answers": ["Galileo", "Sentinel", "Voyager", "Kepler"], "correct": 1, "fact": "Le missioni Sentinel funzionano come diversi insiemi di occhi. Alcune utilizzano il radar, mentre altre osservano la terraferma, gli oceani o l'atmosfera."}, {"question": "Quale missione Copernicus Sentinel utilizza il radar per osservare la Terra?", "answers": ["Sentinel-1", "Sentinel-6", "Sentinel-5P", "Sentinel-2"], "correct": 0, "fact": "Sentinel-1 utilizza il radar, consentendogli di osservare la superficie terrestre giorno e notte e attraverso la copertura nuvolosa."}, {"question": "Quale missione Sentinel \u00e8 particolarmente associata alle immagini dettagliate della superficie terrestre?", "answers": ["Sentinel-2", "Sentinel-3", "Sentinel-5P", "Sentinel-6"], "correct": 0, "fact": "Sentinel-2 fornisce immagini ottiche ad alta risoluzione utili per studiare la vegetazione, la copertura del suolo e molte altre caratteristiche della superficie."}, {"question": "Che cos'\u00e8 Copernicus?", "answers": ["Il programma europeo per l'osservazione della Terra", "Un rover su Marte", "Un tipo di motore a razzo", "Un catalogo stellare"], "correct": 0, "fact": "Copernicus \u00e8 il programma dell'Unione europea per l'osservazione della Terra, che utilizza satelliti e altre fonti per fornire informazioni ambientali."}, {"question": "Perch\u00e9 i satelliti radar possono essere utili durante il tempo nuvoloso?", "answers": ["Il radar pu\u00f2 osservare attraverso le nuvole in molte situazioni", "Il radar trasforma le nuvole in cieli sereni", "Il radar funziona solo al chiuso", "Il radar non pu\u00f2 rilevare la superficie terrestre"], "correct": 0, "fact": "Il radar ad apertura sintetica pu\u00f2 raccogliere osservazioni indipendentemente dalla luce del giorno e pu\u00f2 spesso vedere attraverso la copertura nuvolosa."}, {"question": "Quale tipo di informazioni possono fornire le missioni Sentinel?", "answers": ["Osservazioni della terraferma, degli oceani e dell'atmosfera", "Solo fotografie degli astronauti", "Solo trasmissioni radio", "Solo osservazioni della Luna"], "correct": 0, "fact": "Diverse missioni Sentinel sono progettate per differenti misurazioni ambientali, che comprendono terraferma, oceani e atmosfera."}], "\u20ac2,000": [{"question": "Quale missione dell'ESA ha portato il lander Philae su una cometa nel 2014?", "answers": ["Gaia", "Rosetta", "Euclid", "Solar Orbiter"], "correct": 1, "fact": "Philae rimbalz\u00f2 dopo il primo contatto con la cometa 67P. Nella gravit\u00e0 estremamente debole della cometa, anche un rimbalzo delicato si trasform\u00f2 in un viaggio spettacolare."}, {"question": "Qual era il nome della cometa visitata dalla missione Rosetta dell'ESA?", "answers": ["Halley", "67P/Churyumov-Gerasimenko", "Hale-Bopp", "Shoemaker-Levy 9"], "correct": 1, "fact": "Rosetta raggiunse e studi\u00f2 la cometa 67P/Churyumov-Gerasimenko, orbitandola per pi\u00f9 di due anni."}, {"question": "Che cos'era Philae?", "answers": ["Un lander", "Un telescopio", "Un razzo", "Un satellite per le comunicazioni"], "correct": 0, "fact": "Philae era un piccolo lander robotico trasportato sulla cometa 67P dalla sonda Rosetta dell'ESA."}, {"question": "Che cosa rende particolarmente difficile atterrare su una piccola cometa?", "answers": ["La gravit\u00e0 molto debole", "Troppo ossigeno", "Un'atmosfera densa", "Forti correnti oceaniche"], "correct": 0, "fact": "Una piccola cometa ha una gravit\u00e0 estremamente debole, rendendo difficile per un lander rimanere attaccato alla superficie."}, {"question": "Quanti astronauti dell'ESA sono andati nello spazio da settembre 2021 a settembre 2026?", "answers": ["6", "20", "1", "Nessuno"], "correct": 0, "fact": "Dalla fondazione dell'ESA, un totale di 27 singoli astronauti ha viaggiato nello spazio provenendo da diversi Paesi europei."}, {"question": "Qual era uno dei principali obiettivi scientifici di Rosetta?", "answers": ["Studiare una cometa in dettaglio", "Portare esseri umani su Marte", "Mappare gli oceani della Terra", "Osservare i poli del Sole"], "correct": 0, "fact": "Rosetta studi\u00f2 la composizione, la struttura e l'attivit\u00e0 della cometa 67P per migliorare la nostra comprensione delle comete e del Sistema Solare primordiale."}], "\u20ac4,000": [{"question": "La missione Gaia dell'ESA \u00e8 stata progettata per creare una mappa straordinariamente precisa di che cosa?", "answers": ["Gli oceani della Terra", "I crateri della Luna", "La galassia della Via Lattea", "I vulcani di Marte"], "correct": 2, "fact": "Misurando le posizioni e i movimenti delle stelle, Gaia aiuta gli astronomi a studiare la storia e la struttura della nostra galassia."}, {"question": "Che cosa misura Gaia con grande precisione per le stelle?", "answers": ["Posizioni e movimenti", "Il loro odore", "Solo la loro temperatura superficiale", "Le loro previsioni meteorologiche"], "correct": 0, "fact": "Le misurazioni astrometriche di Gaia rivelano come sono posizionate le stelle e come si muovono attraverso la Via Lattea."}, {"question": "Quale tipo di oggetti osserva principalmente Gaia?", "answers": ["Le stelle", "I vulcani", "Le nuvole", "Gli oceani"], "correct": 0, "fact": "Gaia \u00e8 stata progettata per osservare un numero enorme di stelle e costruire un'immagine tridimensionale precisa della Via Lattea."}, {"question": "Perch\u00e9 i movimenti stellari sono utili agli astronomi?", "answers": ["Rivelano informazioni sulla struttura e sulla storia della Via Lattea", "Prevedono il tempo sulla Terra", "Controllano direttamente i veicoli spaziali", "Creano nuove stelle"], "correct": 0, "fact": "Le posizioni e i movimenti delle stelle contengono indizi su come si \u00e8 formata ed evoluta la nostra galassia."}, {"question": "Quale parte dello spettro elettromagnetico utilizza Gaia per le sue principali misurazioni astrometriche?", "answers": ["La luce visibile", "Solo le onde radio", "Solo i raggi X", "Solo i raggi gamma"], "correct": 0, "fact": "Gaia opera principalmente come missione di astrometria ottica, misurando le posizioni e i movimenti delle stelle con straordinaria precisione."}, {"question": "Che cosa pu\u00f2 aiutare gli scienziati a studiare una mappa dettagliata della Via Lattea?", "answers": ["La formazione e l'evoluzione della galassia", "Il tempo esatto di domani", "Le maree oceaniche su Giove", "Il colore delle nuvole terrestri"], "correct": 0, "fact": "Una mappa stellare precisa aiuta i ricercatori a ricostruire la struttura, la dinamica e la storia della nostra galassia."}], "\u20ac8,000": [{"question": "Quale missione guidata dall'ESA studia il Sole ed \u00e8 progettata per osservare le sue regioni polari?", "answers": ["Solar Orbiter", "JUICE", "Hera", "BepiColombo"], "correct": 0, "fact": "I poli del Sole sono difficili da vedere dalla Terra. Solar Orbiter utilizza sorvoli planetari per inclinare la propria orbita e ottenere una visuale migliore."}, {"question": "Che cosa \u00e8 progettato per studiare Solar Orbiter?", "answers": ["Il Sole", "Le lune di Giove", "Solo le comete", "Solo i ghiacciai della Terra"], "correct": 0, "fact": "Solar Orbiter studia il Sole e il vento solare, aiutando gli scienziati a comprendere il funzionamento della nostra stella."}, {"question": "Perch\u00e9 Solar Orbiter utilizza i sorvoli planetari?", "answers": ["Per cambiare e inclinare la propria orbita", "Per rifornirsi di carburante con la luce solare", "Per atterrare su un pianeta", "Per raccogliere rocce dalla Terra"], "correct": 0, "fact": "Le assistenze gravitazionali dei pianeti possono modificare la traiettoria di un veicolo spaziale e aiutare Solar Orbiter a raggiungere un'orbita con maggiore inclinazione."}, {"question": "Che cos'\u00e8 il vento solare?", "answers": ["Un flusso di particelle cariche provenienti dal Sole", "Il vento nell'atmosfera terrestre", "Un flusso d'acqua su Marte", "Un anello intorno a Saturno"], "correct": 0, "fact": "Il vento solare \u00e8 un flusso continuo di particelle cariche che sfuggono dall'atmosfera esterna del Sole."}, {"question": "Quale caratteristica del Sole \u00e8 particolarmente importante per comprendere la sua attivit\u00e0 magnetica?", "answers": ["Il suo campo magnetico", "I suoi anelli", "I suoi oceani", "La sua superficie solida"], "correct": 0, "fact": "Il campo magnetico del Sole alimenta molte forme di attivit\u00e0 solare, comprese le macchie solari e le eruzioni solari."}, {"question": "Che cosa rende difficile osservare le regioni polari del Sole dalla Terra?", "answers": ["La geometria di osservazione", "La Luna le blocca ogni giorno", "Il Sole non ha poli", "Si trovano dietro Saturno"], "correct": 0, "fact": "Dal consueto punto di vista dalla Terra, i poli del Sole sono visti con un angolo molto ridotto, quindi un veicolo spaziale con un'orbita inclinata pu\u00f2 fornire una nuova prospettiva preziosa."}], "\u20ac16,000": [{"question": "Che cosa possono rilevare i satelliti Copernicus Sentinel in Antartide?", "answers": ["Dinosauri che camminano sotto il ghiaccio", "Cambiamenti nello spessore e nel movimento del ghiaccio", "Messaggi radio alieni", "Vulcani su Marte"], "correct": 1, "fact": "I satelliti radar possono osservare il ghiaccio anche attraverso le nuvole e durante la lunga notte polare, rendendoli strumenti preziosi per monitorare i cambiamenti."}, {"question": "Perch\u00e9 il radar \u00e8 particolarmente utile per osservare l'Antartide?", "answers": ["Pu\u00f2 funzionare senza luce solare e attraverso la copertura nuvolosa", "Scioglie il ghiaccio", "Funziona solo a mezzogiorno", "Ha sempre bisogno di cieli sereni"], "correct": 0, "fact": "Gli strumenti radar possono raccogliere osservazioni al buio e dipendono molto meno dall'assenza di nuvole rispetto agli strumenti ottici."}, {"question": "Che cosa possono rivelare le osservazioni satellitari sui ghiacciai?", "answers": ["Cambiamenti nel loro movimento", "Il loro sapore", "L'et\u00e0 esatta di ogni fiocco di neve", "La loro temperatura interna ovunque"], "correct": 0, "fact": "Osservazioni satellitari ripetute possono mostrare quanto velocemente si muovono i ghiacciai e i flussi di ghiaccio e come questi schemi cambiano nel tempo."}, {"question": "Che cos'\u00e8 una calotta glaciale?", "answers": ["Una vasta massa di ghiaccio continentale che ricopre una grande area", "Uno strato di acqua marina", "Una formazione nuvolosa", "Un flusso di lava vulcanica"], "correct": 0, "fact": "Le calotte glaciali dell'Antartide e della Groenlandia sono enormi masse di ghiaccio continentale che contengono la maggior parte del ghiaccio d'acqua dolce della Terra."}, {"question": "Quale tipo di cambiamento pu\u00f2 rilevare il radar satellitare sulla superficie del ghiaccio?", "answers": ["Movimento e deformazione", "Solo il colore", "Solo la temperatura dell'aria", "Solo l'et\u00e0 del ghiaccio"], "correct": 0, "fact": "Le misurazioni radar possono essere utilizzate per rilevare il movimento e la deformazione della superficie, compresi i cambiamenti nei ghiacciai e nelle calotte glaciali."}, {"question": "Perch\u00e9 il monitoraggio del ghiaccio antartico \u00e8 importante per le scienze della Terra?", "answers": ["Aiuta a monitorare i cambiamenti nell'ambiente polare", "Determina il numero di stelle nella Via Lattea", "Misura l'atmosfera di Giove", "Sostituisce tutti i modelli climatici"], "correct": 0, "fact": "Le osservazioni a lungo termine del ghiaccio antartico aiutano gli scienziati a comprendere i cambiamenti nell'ambiente polare e i loro effetti pi\u00f9 ampi."}], "\u20ac24,000": [{"question": "Che cosa significa il nome JUICE?", "answers": ["Jupiter Investigation of Comets and Exploration", "Joint Universe Ice and Climate Explorer", "Jupiter Icy Moons Explorer", "Journey Into Cosmic Evolution"], "correct": 2, "fact": "JUICE sta viaggiando verso il sistema di Giove per studiare il pianeta gigante e le sue lune ghiacciate che ospitano oceani."}, {"question": "Quale pianeta sta studiando JUICE?", "answers": ["Marte", "Giove", "Saturno", "Venere"], "correct": 1, "fact": "JUICE \u00e8 la missione dell'ESA Jupiter Icy Moons Explorer ed \u00e8 progettata per studiare Giove e diverse delle sue grandi lune ghiacciate."}, {"question": "Quale di queste \u00e8 una delle lune ghiacciate studiate da JUICE?", "answers": ["Ganimede", "Fobos", "Titano", "Tritone"], "correct": 0, "fact": "JUICE studier\u00e0 Ganimede in dettaglio e osserver\u00e0 anche Europa e Callisto durante la sua missione."}, {"question": "Che cosa \u00e8 particolarmente interessante delle lune ghiacciate di Giove?", "answers": ["Alcune potrebbero contenere oceani sotterranei", "Hanno tutte l'atmosfera della Terra", "Sono pi\u00f9 calde del Sole", "Sono composte interamente di metallo"], "correct": 0, "fact": "Le prove indicano che alcune delle lune ghiacciate di Giove contengono oceani sotto le loro superfici ghiacciate."}, {"question": "Quale luna \u00e8 prevista come obiettivo principale della missione orbitale di JUICE?", "answers": ["Ganimede", "Io", "Europa", "Amaltea"], "correct": 0, "fact": "\u00c8 previsto che JUICE entri in orbita attorno a Ganimede, diventando il primo veicolo spaziale a orbitare attorno a una luna diversa dalla Luna della Terra."}, {"question": "Perch\u00e9 le lune ghiacciate sono interessanti nella ricerca di ambienti potenzialmente abitabili?", "answers": ["Potrebbero avere acqua liquida sotto il ghiaccio", "Sono tutte vicine al Sole", "Hanno i continenti della Terra", "Sono composte di ossigeno puro"], "correct": 0, "fact": "L'acqua liquida \u00e8 uno degli ingredienti che gli scienziati considerano importanti nello studio di ambienti che potrebbero sostenere qualche forma di vita."}], "\u20ac44,000": [{"question": "Quale missione ESA-JAXA utilizza una complessa serie di sorvoli planetari nel suo viaggio verso Mercurio?", "answers": ["Euclid", "Sentinel-2", "BepiColombo", "Philae"], "correct": 2, "fact": "Raggiungere Mercurio \u00e8 sorprendentemente difficile. Un veicolo spaziale deve perdere una grande quantit\u00e0 di energia orbitale, quindi BepiColombo utilizza i sorvoli come manovre di guida cosmica attentamente pianificate."}, {"question": "Quale pianeta \u00e8 la destinazione principale di BepiColombo?", "answers": ["Mercurio", "Marte", "Giove", "Venere"], "correct": 0, "fact": "BepiColombo \u00e8 una missione congiunta ESA-JAXA progettata per studiare Mercurio, il pianeta pi\u00f9 interno del Sistema Solare."}, {"question": "Perch\u00e9 raggiungere Mercurio \u00e8 particolarmente difficile per un veicolo spaziale dalla Terra?", "answers": ["Deve perdere energia orbitale per avvicinarsi al Sole", "Mercurio ha un'atmosfera densa", "Mercurio \u00e8 fuori dal Sistema Solare", "Ha oceani che bloccano i veicoli spaziali"], "correct": 0, "fact": "Un veicolo spaziale che viaggia dalla Terra deve liberarsi di una quantit\u00e0 sostanziale di energia orbitale per entrare in un'orbita vicina al Sole, rendendo Mercurio una destinazione impegnativa."}, {"question": "Quando \u00e8 stata fondata l'ESA?", "answers": ["1975", "1965", "1970", "1985"], "correct": 0, "fact": "JAXA \u00e8 l'agenzia spaziale nazionale e l'organizzazione di ricerca del Giappone. BepiColombo \u00e8 una collaborazione tra JAXA ed ESA."}, {"question": "Dove si trova la sede centrale dell'ESA?", "answers": ["Parigi, Francia", "Berlino, Germania", "Roma, Italia", "Londra, Regno Unito"], "correct": 0, "fact": "L'ESA ha 23 Stati membri e sette principali strutture in Europa; la sua sede centrale si trova nel centro di Parigi."}, {"question": "Qual \u00e8 la pi\u00f9 grande struttura dell'ESA?", "answers": ["ESRIN, Italia", "ESTEC, Paesi Bassi", "ESOC, Germania", "Sede centrale dell'ESA, Francia"], "correct": 1, "fact": "ESTEC \u00e8 il Centro europeo per la ricerca e la tecnologia spaziale, il cuore tecnico dell'ESA, dove nasce la maggior parte dei progetti dell'ESA e dove vengono guidati attraverso le varie fasi di sviluppo."}]}, "de": {"\u20ac100": [{"question": "Wof\u00fcr steht ESA?", "answers": ["Europ\u00e4ische Wissenschaftsallianz", "Europ\u00e4ische Satellitenagentur", "Europ\u00e4ische Weltraumorganisation", "Europ\u00e4ische Weltraumvereinigung"], "correct": 2, "fact": "Die ESA bringt europ\u00e4ische L\u00e4nder zusammen, um den Weltraum zu erforschen und Raumfahrttechnologie zum Nutzen der Menschen auf der Erde einzusetzen."}, {"question": "Was erforscht und erkundet die ESA unter anderem haupts\u00e4chlich?", "answers": ["Die Ozeane", "Den Weltraum und die Erde aus dem Weltraum", "Das Erdinnere", "Alles oben Genannte"], "correct": 3, "fact": "Die ESA entwickelt und betreibt Weltraummissionen, die die Erde einschlie\u00dflich ihrer unterirdischen Zusammensetzung und ihrer inneren Strukturen, das Sonnensystem und das weitere Universum untersuchen."}, {"question": "Was ist der Hauptzweck der ESA?", "answers": ["Raumfahrtforschung, -technologie und -anwendungen zu f\u00f6rdern", "Flugzeuge zu bauen", "Flugh\u00e4fen zu betreiben", "Wettervorhersagen bereitzustellen"], "correct": 0, "fact": "Der Zweck der ESA besteht darin, ausschlie\u00dflich f\u00fcr friedliche Zwecke die Zusammenarbeit zwischen europ\u00e4ischen Staaten in der Weltraumforschung und -technologie zu erm\u00f6glichen und zu f\u00f6rdern."}, {"question": "Was ist die ESA?", "answers": ["Eine Universit\u00e4t", "Eine europ\u00e4ische Organisation", "Ein privates Unternehmen", "Eine Fluggesellschaft"], "correct": 1, "fact": "ESA steht f\u00fcr European Space Agency (Europ\u00e4ische Weltraumorganisation), eine internationale Organisation, die die Entwicklung der europ\u00e4ischen Raumfahrtkapazit\u00e4ten gestaltet und sicherstellt, dass Investitionen in den Weltraum den B\u00fcrgerinnen und B\u00fcrgern Europas und der Welt weiterhin zugutekommen."}, {"question": "Arbeitet die ESA mit Astronauten zusammen?", "answers": ["Ja, mit ESA-Astronauten", "Nein, aber sie arbeitet mit Piloten zusammen", "Ja, aber nur mit NASA-Astronauten", "Nein, sie arbeitet nur mit Wissenschaftlern auf der Erde zusammen"], "correct": 0, "fact": "Die ESA bildet ein Team von Astronauten aus verschiedenen europ\u00e4ischen L\u00e4ndern aus und h\u00e4lt es bereit, um den Weltraum zu erforschen."}, {"question": "Welches ist ein Arbeitsbereich der ESA?", "answers": ["Raumfahrttechnologie", "Modedesign", "Lebensmittelproduktion", "Stra\u00dfenverkehr"], "correct": 0, "fact": "Der Zweck der ESA besteht darin, ausschlie\u00dflich f\u00fcr friedliche Zwecke die Zusammenarbeit zwischen europ\u00e4ischen Staaten in der Weltraumforschung und -technologie zu erm\u00f6glichen und zu f\u00f6rdern."}], "\u20ac200": [{"question": "Welcher Planet ist als \u201eRoter Planet\u201c bekannt?", "answers": ["Venus", "Mars", "Jupiter", "Merkur"], "correct": 1, "fact": "Der Mars erscheint r\u00f6tlich, weil Eisenminerale in seinem Boden oxidiert sind \u2013 ein Prozess, der dem Rosten \u00e4hnelt."}, {"question": "Welcher Planet ist der gr\u00f6\u00dfte in unserem Sonnensystem?", "answers": ["Erde", "Saturn", "Jupiter", "Neptun"], "correct": 2, "fact": "Jupiter ist der gr\u00f6\u00dfte Planet im Sonnensystem und hat einen Durchmesser, der mehr als elfmal so gro\u00df ist wie der der Erde."}, {"question": "Welcher Planet ist f\u00fcr sein ausgepr\u00e4gtes Ringsystem bekannt?", "answers": ["Mars", "Saturn", "Venus", "Merkur"], "correct": 1, "fact": "Die Ringe des Saturn bestehen haupts\u00e4chlich aus unz\u00e4hligen Eis- und Gesteinsst\u00fccken."}, {"question": "Welcher Planet ist der Sonne am n\u00e4chsten?", "answers": ["Venus", "Erde", "Merkur", "Mars"], "correct": 2, "fact": "Merkur ist der innerste Planet und vollendet einen Umlauf um die Sonne in etwa 88 Erdentagen."}, {"question": "Welcher Planet wird wegen seiner \u00e4hnlichen Gr\u00f6\u00dfe manchmal als Schwesterplanet der Erde bezeichnet?", "answers": ["Jupiter", "Venus", "Mars", "Neptun"], "correct": 1, "fact": "Die Venus \u00e4hnelt der Erde in Gr\u00f6\u00dfe und Zusammensetzung, obwohl sich die Bedingungen auf ihrer Oberfl\u00e4che stark unterscheiden."}, {"question": "Wie hei\u00dft die Galaxie, die unser Sonnensystem enth\u00e4lt?", "answers": ["Andromeda", "Die Milchstra\u00dfe", "Whirlpool", "Sombrero"], "correct": 1, "fact": "Unser Sonnensystem befindet sich in der Milchstra\u00dfe, einer Balkenspiralgalaxie mit Hunderten Milliarden Sternen."}], "\u20ac500": [{"question": "Wof\u00fcr werden Erdbeobachtungssatelliten haupts\u00e4chlich eingesetzt?", "answers": ["Nur f\u00fcr Wettervorhersagen", "Zur \u00dcberwachung der Erde und von Umweltver\u00e4nderungen", "Nur f\u00fcr die Ausstrahlung von Fernsehen", "Zum Aufnehmen von Urlaubsfotos"], "correct": 1, "fact": "Satellitendaten k\u00f6nnen helfen, W\u00e4lder, Meereis, Luftqualit\u00e4t, \u00dcberschwemmungen, Br\u00e4nde, Nutzpflanzen und viele andere Ver\u00e4nderungen auf unserem Planeten zu \u00fcberwachen."}, {"question": "Was k\u00f6nnen Satelliten Wissenschaftlern helfen, \u00fcber gro\u00dfe Gebiete zu \u00fcberwachen?", "answers": ["Ver\u00e4nderungen in W\u00e4ldern", "Nur einzelne H\u00e4user", "Nur unterirdische H\u00f6hlen", "Nichts auf der Erdoberfl\u00e4che"], "correct": 0, "fact": "Erdbeobachtungssatelliten k\u00f6nnen gro\u00dfe Gebiete wiederholt erfassen und so dabei helfen, Ver\u00e4nderungen in W\u00e4ldern, der Landwirtschaft und \u00d6kosystemen zu verfolgen."}, {"question": "Warum sind Satelliten n\u00fctzlich, um abgelegene Teile der Erde zu beobachten?", "answers": ["Sie k\u00f6nnen gro\u00dfe Gebiete aus dem Orbit beobachten", "Sie ben\u00f6tigen niemals Instrumente", "Sie funktionieren nur \u00fcber St\u00e4dten", "Sie ersetzen alle Messungen am Boden"], "correct": 0, "fact": "Satelliten k\u00f6nnen wiederholte Beobachtungen von Orten liefern, die vom Boden aus schwer oder gef\u00e4hrlich zu erreichen sind."}, {"question": "Welches Ereignis k\u00f6nnen Erdbeobachtungssatelliten bei der \u00dcberwachung unterst\u00fctzen?", "answers": ["\u00dcberschwemmungen", "Nur Sonnenfinsternisse", "Nur Meteorschauer", "Nur Raketenstarts"], "correct": 0, "fact": "Satellitenbeobachtungen k\u00f6nnen dabei helfen, \u00fcberschwemmte Gebiete zu kartieren und die \u00dcberwachung vor, w\u00e4hrend und nach gro\u00dfen \u00dcberschwemmungen zu unterst\u00fctzen."}, {"question": "Was k\u00f6nnen Satellitenbeobachtungen im Ozean \u00fcberwachen?", "answers": ["Die Ausdehnung des Meereises", "Nur Fische in einzelnen Netzen", "Nur Schiffe in H\u00e4fen", "Nichts"], "correct": 0, "fact": "Satellitenbeobachtungen k\u00f6nnen Meereis und viele andere gro\u00dfr\u00e4umige Ver\u00e4nderungen im Ozean und an den K\u00fcsten verfolgen."}, {"question": "Was ist ein Vorteil der Beobachtung der Erde aus dem Weltraum?", "answers": ["Globale oder regionale Abdeckung", "Es ist keine Datenverarbeitung erforderlich", "Wolken k\u00f6nnen Beobachtungen niemals beeintr\u00e4chtigen", "Jeder Satellit sieht alles"], "correct": 0, "fact": "Verschiedene Satelliteninstrumente bieten eine gro\u00dffl\u00e4chige Abdeckung und wiederholte Messungen, die Beobachtungen vom Boden erg\u00e4nzen."}], "\u20ac1,200": [{"question": "Wie hei\u00dft die europ\u00e4ische Familie von Erdbeobachtungsmissionen, die vom Copernicus-Programm genutzt wird?", "answers": ["Galileo", "Sentinel", "Voyager", "Kepler"], "correct": 1, "fact": "Die Sentinel-Missionen wirken wie verschiedene Augenpaare. Einige nutzen Radar, w\u00e4hrend andere Land, Ozeane oder die Atmosph\u00e4re beobachten."}, {"question": "Welche Copernicus-Sentinel-Mission nutzt Radar zur Beobachtung der Erde?", "answers": ["Sentinel-1", "Sentinel-6", "Sentinel-5P", "Sentinel-2"], "correct": 0, "fact": "Sentinel-1 nutzt Radar und kann dadurch die Erdoberfl\u00e4che bei Tag und Nacht sowie durch Wolken hindurch beobachten."}, {"question": "Welche Sentinel-Mission ist besonders f\u00fcr detaillierte Bilder der Landoberfl\u00e4che bekannt?", "answers": ["Sentinel-2", "Sentinel-3", "Sentinel-5P", "Sentinel-6"], "correct": 0, "fact": "Sentinel-2 liefert hochaufl\u00f6sende optische Bilder, die sich zur Untersuchung von Vegetation, Landbedeckung und vielen anderen Oberfl\u00e4chenmerkmalen eignen."}, {"question": "Was ist Copernicus?", "answers": ["Europas Erdbeobachtungsprogramm", "Ein Marsrover", "Eine Art Raketentriebwerk", "Ein Sternenkatalog"], "correct": 0, "fact": "Copernicus ist das Erdbeobachtungsprogramm der Europ\u00e4ischen Union, das Satelliten und andere Quellen nutzt, um Umweltinformationen bereitzustellen."}, {"question": "Warum k\u00f6nnen Radarsatelliten bei bew\u00f6lktem Wetter n\u00fctzlich sein?", "answers": ["Radar kann unter vielen Bedingungen durch Wolken hindurch beobachten", "Radar verwandelt Wolken in klaren Himmel", "Radar funktioniert nur in Innenr\u00e4umen", "Radar kann die Erdoberfl\u00e4che nicht erkennen"], "correct": 0, "fact": "Radar mit synthetischer Apertur kann unabh\u00e4ngig vom Tageslicht n\u00fctzliche Beobachtungen erfassen und h\u00e4ufig durch Wolken hindurchsehen."}, {"question": "Welche Art von Informationen k\u00f6nnen Sentinel-Missionen liefern?", "answers": ["Beobachtungen von Land, Ozeanen und Atmosph\u00e4re", "Nur Fotos von Astronauten", "Nur Radiosendungen", "Nur Beobachtungen des Mondes"], "correct": 0, "fact": "Verschiedene Sentinel-Missionen sind f\u00fcr unterschiedliche Umweltmessungen ausgelegt und erfassen Land, Ozeane und die Atmosph\u00e4re."}], "\u20ac2,000": [{"question": "Welche ESA-Mission setzte 2014 die Landeeinheit Philae auf einem Kometen ab?", "answers": ["Gaia", "Rosetta", "Euclid", "Solar Orbiter"], "correct": 1, "fact": "Philae prallte nach seiner ersten Landung auf dem Kometen 67P ab. Aufgrund der extrem schwachen Gravitation des Kometen wurde selbst ein sanfter Sprung zu einer dramatischen Reise."}, {"question": "Wie hie\u00df der Komet, den die ESA-Mission Rosetta besuchte?", "answers": ["Halley", "67P/Churyumov-Gerasimenko", "Hale-Bopp", "Shoemaker-Levy 9"], "correct": 1, "fact": "Rosetta reiste zum Kometen 67P/Churyumov-Gerasimenko, untersuchte ihn und umkreiste ihn mehr als zwei Jahre lang."}, {"question": "Was war Philae?", "answers": ["Eine Landeeinheit", "Ein Teleskop", "Eine Rakete", "Ein Kommunikationssatellit"], "correct": 0, "fact": "Philae war eine kleine robotische Landeeinheit, die von der Raumsonde Rosetta der ESA zum Kometen 67P gebracht wurde."}, {"question": "Was macht die Landung auf einem kleinen Kometen besonders schwierig?", "answers": ["Sehr schwache Gravitation", "Zu viel Sauerstoff", "Eine dichte Atmosph\u00e4re", "Starke Meeresstr\u00f6mungen"], "correct": 0, "fact": "Ein kleiner Komet hat eine extrem schwache Gravitation, wodurch es f\u00fcr eine Landeeinheit schwierig ist, an der Oberfl\u00e4che haften zu bleiben."}, {"question": "Wie viele ESA-Astronauten flogen von September 2021 bis September 2026 ins All?", "answers": ["6", "20", "1", "Keine"], "correct": 0, "fact": "Seit der Gr\u00fcndung der ESA sind insgesamt 27 einzelne Astronauten aus verschiedenen europ\u00e4ischen L\u00e4ndern ins All geflogen."}, {"question": "Was war ein wichtiges wissenschaftliches Ziel von Rosetta?", "answers": ["Einen Kometen detailliert zu untersuchen", "Menschen auf dem Mars zu landen", "Die Ozeane der Erde zu kartieren", "Die Pole der Sonne zu beobachten"], "correct": 0, "fact": "Rosetta untersuchte die Zusammensetzung, Struktur und Aktivit\u00e4t des Kometen 67P, um unser Verst\u00e4ndnis von Kometen und des fr\u00fchen Sonnensystems zu verbessern."}], "\u20ac4,000": [{"question": "Die Gaia-Mission der ESA wurde entwickelt, um eine au\u00dfergew\u00f6hnlich pr\u00e4zise Karte wovon zu erstellen?", "answers": ["Der Ozeane der Erde", "Der Krater des Mondes", "Der Milchstra\u00dfe", "Der Vulkane des Mars"], "correct": 2, "fact": "Durch die Messung der Positionen und Bewegungen von Sternen hilft Gaia Astronomen, die Geschichte und Struktur unserer Galaxie zu untersuchen."}, {"question": "Was misst Gaia bei Sternen mit sehr hoher Pr\u00e4zision?", "answers": ["Positionen und Bewegungen", "Ihren Geruch", "Nur ihre Oberfl\u00e4chentemperatur", "Ihre Wettervorhersagen"], "correct": 0, "fact": "Gaias astrometrische Messungen zeigen, wo Sterne in der Milchstra\u00dfe positioniert sind und wie sie sich bewegen."}, {"question": "Welche Art von Objekten erfasst Gaia haupts\u00e4chlich?", "answers": ["Sterne", "Vulkane", "Wolken", "Ozeane"], "correct": 0, "fact": "Gaia wurde entwickelt, um eine enorme Anzahl von Sternen zu erfassen und ein pr\u00e4zises dreidimensionales Bild der Milchstra\u00dfe zu erstellen."}, {"question": "Warum sind Sternbewegungen f\u00fcr Astronomen n\u00fctzlich?", "answers": ["Sie liefern Informationen \u00fcber die Struktur und Geschichte der Milchstra\u00dfe", "Sie sagen das Wetter auf der Erde voraus", "Sie steuern Raumfahrzeuge direkt", "Sie erzeugen neue Sterne"], "correct": 0, "fact": "Die Positionen und Bewegungen von Sternen enthalten Hinweise darauf, wie unsere Galaxie entstanden ist und sich entwickelt hat."}, {"question": "Welchen Teil des elektromagnetischen Spektrums nutzt Gaia f\u00fcr seine wichtigsten astrometrischen Messungen?", "answers": ["Sichtbares Licht", "Nur Radiowellen", "Nur R\u00f6ntgenstrahlung", "Nur Gammastrahlung"], "correct": 0, "fact": "Gaia arbeitet haupts\u00e4chlich als optische Astrometrie-Mission und misst die Positionen und Bewegungen von Sternen mit au\u00dfergew\u00f6hnlicher Pr\u00e4zision."}, {"question": "Was k\u00f6nnen Wissenschaftler mithilfe einer detaillierten Karte der Milchstra\u00dfe untersuchen?", "answers": ["Die Entstehung und Entwicklung der Galaxie", "Das genaue Wetter von morgen", "Gezeiten auf dem Jupiter", "Die Farbe der Wolken der Erde"], "correct": 0, "fact": "Eine pr\u00e4zise Sternkarte hilft Forschern, die Struktur, Dynamik und Geschichte unserer Galaxie zu rekonstruieren."}], "\u20ac8,000": [{"question": "Welche von der ESA geleitete Mission untersucht die Sonne und soll ihre Polarregionen beobachten?", "answers": ["Solar Orbiter", "JUICE", "Hera", "BepiColombo"], "correct": 0, "fact": "Die Pole der Sonne sind von der Erde aus schwer zu sehen. Solar Orbiter nutzt Vorbeifl\u00fcge an Planeten, um seine Umlaufbahn zu neigen und einen besseren Blick zu erhalten."}, {"question": "Was soll Solar Orbiter untersuchen?", "answers": ["Die Sonne", "Die Monde des Jupiter", "Nur Kometen", "Nur die Gletscher der Erde"], "correct": 0, "fact": "Solar Orbiter untersucht die Sonne und den Sonnenwind und hilft Wissenschaftlern zu verstehen, wie unser Stern funktioniert."}, {"question": "Warum nutzt Solar Orbiter Vorbeifl\u00fcge an Planeten?", "answers": ["Um seine Umlaufbahn zu ver\u00e4ndern und zu neigen", "Um mit Sonnenlicht aufzutanken", "Um auf einem Planeten zu landen", "Um Gestein von der Erde zu sammeln"], "correct": 0, "fact": "Gravitationsman\u00f6ver an Planeten k\u00f6nnen die Flugbahn eines Raumfahrzeugs ver\u00e4ndern und Solar Orbiter dabei helfen, eine Umlaufbahn mit h\u00f6herer Neigung zu erreichen."}, {"question": "Was ist der Sonnenwind?", "answers": ["Ein Strom geladener Teilchen von der Sonne", "Wind in der Erdatmosph\u00e4re", "Ein Wasserstrom auf dem Mars", "Ein Ring um den Saturn"], "correct": 0, "fact": "Der Sonnenwind ist ein kontinuierlicher Strom geladener Teilchen, die aus der \u00e4u\u00dferen Atmosph\u00e4re der Sonne entweichen."}, {"question": "Welche Eigenschaft der Sonne ist besonders wichtig, um ihre magnetische Aktivit\u00e4t zu verstehen?", "answers": ["Ihr Magnetfeld", "Ihre Ringe", "Ihre Ozeane", "Ihre feste Oberfl\u00e4che"], "correct": 0, "fact": "Das Magnetfeld der Sonne treibt viele Formen solaren Aktivit\u00e4t an, darunter Sonnenflecken und Sonneneruptionen."}, {"question": "Was macht die Beobachtung der Polarregionen der Sonne von der Erde aus schwierig?", "answers": ["Die Beobachtungsgeometrie", "Der Mond verdeckt sie jeden Tag", "Die Sonne hat keine Pole", "Sie liegen hinter dem Saturn"], "correct": 0, "fact": "Von der \u00fcblichen Perspektive der Erde aus werden die Pole der Sonne in einem sehr flachen Winkel gesehen, sodass ein Raumfahrzeug mit geneigter Umlaufbahn eine wertvolle neue Perspektive bieten kann."}], "\u20ac16,000": [{"question": "Was k\u00f6nnen Copernicus-Sentinel-Satelliten in der Antarktis erkennen?", "answers": ["Dinosaurier, die unter dem Eis laufen", "Ver\u00e4nderungen der Dicke und Bewegung des Eises", "Au\u00dferirdische Funksignale", "Vulkane auf dem Mars"], "correct": 1, "fact": "Radarsatelliten k\u00f6nnen Eis auch durch Wolken und w\u00e4hrend der langen Polarnacht beobachten, wodurch sie wertvolle Instrumente zur Verfolgung von Ver\u00e4nderungen sind."}, {"question": "Warum ist Radar f\u00fcr die Beobachtung der Antarktis besonders n\u00fctzlich?", "answers": ["Es kann ohne Sonnenlicht und durch Wolken hindurch arbeiten", "Es schmilzt das Eis", "Es funktioniert nur mittags", "Es ben\u00f6tigt jederzeit einen wolkenlosen Himmel"], "correct": 0, "fact": "Radarinstrumente k\u00f6nnen im Dunkeln Beobachtungen erfassen und sind wesentlich weniger auf wolkenfreie Bedingungen angewiesen als optische Instrumente."}, {"question": "Was k\u00f6nnen Satellitenbeobachtungen \u00fcber Gletscher zeigen?", "answers": ["Ver\u00e4nderungen ihrer Bewegung", "Ihren Geschmack", "Das genaue Alter jeder Schneeflocke", "Ihre innere Temperatur \u00fcberall"], "correct": 0, "fact": "Wiederholte Satellitenbeobachtungen k\u00f6nnen zeigen, wie schnell sich Gletscher und Eisstr\u00f6me bewegen und wie sich diese Muster im Laufe der Zeit ver\u00e4ndern."}, {"question": "Was ist ein Eisschild?", "answers": ["Eine riesige Masse von Landeis, die ein gro\u00dfes Gebiet bedeckt", "Eine Schicht Meerwasser", "Eine Wolkenformation", "Ein vulkanischer Lavastrom"], "correct": 0, "fact": "Die Eisschilde der Antarktis und Gr\u00f6nlands sind riesige Massen von Landeis, die den gr\u00f6\u00dften Teil des S\u00fc\u00dfwassereises der Erde enthalten."}, {"question": "Welche Art von Ver\u00e4nderung kann Satellitenradar auf einer Eisoberfl\u00e4che erkennen?", "answers": ["Bewegung und Verformung", "Nur Farbe", "Nur Lufttemperatur", "Nur das Alter des Eises"], "correct": 0, "fact": "Radarmessungen k\u00f6nnen genutzt werden, um Oberfl\u00e4chenbewegungen und Verformungen zu erkennen, darunter Ver\u00e4nderungen an Gletschern und Eisschilden."}, {"question": "Warum ist die \u00dcberwachung des antarktischen Eises f\u00fcr die Erdwissenschaft wichtig?", "answers": ["Sie hilft, Ver\u00e4nderungen in der Polarregion zu verfolgen", "Sie bestimmt die Anzahl der Sterne in der Milchstra\u00dfe", "Sie misst die Atmosph\u00e4re des Jupiter", "Sie ersetzt alle Klimamodelle"], "correct": 0, "fact": "Langfristige Beobachtungen des antarktischen Eises helfen Wissenschaftlern, Ver\u00e4nderungen in der Polarregion und deren weiterreichende Auswirkungen zu verstehen."}], "\u20ac24,000": [{"question": "Wof\u00fcr steht der Name JUICE?", "answers": ["Jupiter Investigation of Comets and Exploration", "Joint Universe Ice and Climate Explorer", "Jupiter Icy Moons Explorer", "Journey Into Cosmic Evolution"], "correct": 2, "fact": "JUICE ist auf dem Weg zum Jupiter-System, um den Gasriesen und seine eisigen Monde mit Ozeanen im Inneren zu untersuchen."}, {"question": "Welchen Planeten soll JUICE untersuchen?", "answers": ["Mars", "Jupiter", "Saturn", "Venus"], "correct": 1, "fact": "JUICE ist der Jupiter Icy Moons Explorer der ESA und soll Jupiter sowie mehrere seiner gro\u00dfen eisigen Monde untersuchen."}, {"question": "Welcher dieser Monde ist einer der von JUICE untersuchten eisigen Monde?", "answers": ["Ganymed", "Phobos", "Titan", "Triton"], "correct": 0, "fact": "JUICE wird Ganymed detailliert untersuchen und w\u00e4hrend seiner Mission auch Beobachtungen von Europa und Kallisto durchf\u00fchren."}, {"question": "Was ist an den eisigen Monden des Jupiter besonders interessant?", "answers": ["Einige k\u00f6nnten unterirdische Ozeane enthalten", "Sie haben alle die Atmosph\u00e4re der Erde", "Sie sind hei\u00dfer als die Sonne", "Sie bestehen vollst\u00e4ndig aus Metall"], "correct": 0, "fact": "Beobachtungen deuten darauf hin, dass einige der eisigen Monde des Jupiter Ozeane unter ihren gefrorenen Oberfl\u00e4chen enthalten."}, {"question": "Welcher Mond soll das Hauptziel der Umlaufmission von JUICE werden?", "answers": ["Ganymed", "Io", "Europa", "Amalthea"], "correct": 0, "fact": "JUICE soll in eine Umlaufbahn um Ganymed eintreten und w\u00e4re damit die erste Raumsonde, die einen anderen Mond als den Erdmond umkreist."}, {"question": "Warum sind eisige Monde bei der Suche nach potenziell bewohnbaren Umgebungen interessant?", "answers": ["Sie k\u00f6nnten unter ihrem Eis fl\u00fcssiges Wasser haben", "Sie liegen alle nahe an der Sonne", "Sie haben die Kontinente der Erde", "Sie bestehen aus reinem Sauerstoff"], "correct": 0, "fact": "Fl\u00fcssiges Wasser ist einer der Bestandteile, die Wissenschaftler bei der Untersuchung von Umgebungen f\u00fcr wichtig halten, in denen m\u00f6glicherweise eine Form von Leben existieren k\u00f6nnte."}], "\u20ac44,000": [{"question": "Welche ESA-JAXA-Mission nutzt auf ihrem Weg zum Merkur eine komplexe Reihe von Vorbeifl\u00fcgen an Planeten?", "answers": ["Euclid", "Sentinel-2", "BepiColombo", "Philae"], "correct": 2, "fact": "Zum Merkur zu gelangen ist \u00fcberraschend schwierig. Ein Raumfahrzeug muss viel Umlaufenergie verlieren, daher nutzt BepiColombo Vorbeifl\u00fcge als sorgf\u00e4ltig geplante kosmische Steuerungsman\u00f6ver."}, {"question": "Welcher Planet ist das Hauptziel von BepiColombo?", "answers": ["Merkur", "Mars", "Jupiter", "Venus"], "correct": 0, "fact": "BepiColombo ist eine gemeinsame Mission von ESA und JAXA zur Untersuchung des Merkur, des innersten Planeten des Sonnensystems."}, {"question": "Warum ist es f\u00fcr ein Raumfahrzeug von der Erde besonders schwierig, den Merkur zu erreichen?", "answers": ["Es muss Umlaufenergie verlieren, um n\u00e4her zur Sonne zu gelangen", "Merkur hat eine dichte Atmosph\u00e4re", "Merkur liegt au\u00dferhalb des Sonnensystems", "Er hat Ozeane, die Raumfahrzeuge blockieren"], "correct": 0, "fact": "Ein von der Erde startendes Raumfahrzeug muss erhebliche Umlaufenergie abbauen, um in eine Umlaufbahn nahe der Sonne zu gelangen, wodurch Merkur zu einem anspruchsvollen Ziel wird."}, {"question": "Wann wurde die ESA gegr\u00fcndet?", "answers": ["1975", "1965", "1970", "1985"], "correct": 0, "fact": "JAXA ist Japans nationale Raumfahrtagentur und Forschungsorganisation. BepiColombo ist eine Zusammenarbeit zwischen JAXA und ESA."}, {"question": "Wo befindet sich der Hauptsitz der ESA?", "answers": ["Paris, Frankreich", "Berlin, Deutschland", "Rom, Italien", "London, Vereinigtes K\u00f6nigreich"], "correct": 0, "fact": "Die ESA hat 23 Mitgliedstaaten und sieben wichtige Einrichtungen in Europa; ihr Hauptsitz befindet sich im Zentrum von Paris."}, {"question": "Welche ist die gr\u00f6\u00dfte Einrichtung der ESA?", "answers": ["ESRIN, Italien", "ESTEC, Niederlande", "ESOC, Deutschland", "ESA-Hauptsitz, Frankreich"], "correct": 1, "fact": "ESTEC ist das Europ\u00e4ische Zentrum f\u00fcr Weltraumforschung und -technologie, das technische Herz der ESA. Dort entstehen die meisten ESA-Projekte und werden durch die verschiedenen Entwicklungsphasen begleitet."}]}, "fr": {"\u20ac100": [{"question": "Que signifie ESA ?", "answers": ["Alliance scientifique europ\u00e9enne", "Agence satellitaire europ\u00e9enne", "Agence spatiale europ\u00e9enne", "Association spatiale europ\u00e9enne"], "correct": 2, "fact": "L\u2019ESA r\u00e9unit les pays europ\u00e9ens pour explorer l\u2019espace et utiliser les technologies spatiales au b\u00e9n\u00e9fice des populations sur Terre."}, {"question": "Entre autres, qu\u2019\u00e9tudie et explore principalement l\u2019ESA ?", "answers": ["Les oc\u00e9ans", "L\u2019espace et la Terre depuis l\u2019espace", "Le sous-sol terrestre", "Toutes les r\u00e9ponses ci-dessus"], "correct": 3, "fact": "L\u2019ESA d\u00e9veloppe et exploite des missions spatiales qui \u00e9tudient la Terre, notamment la composition de son sous-sol et les structures de son int\u00e9rieur, ainsi que le Syst\u00e8me solaire et l\u2019Univers au sens large."}, {"question": "Quel est l\u2019objectif principal de l\u2019ESA ?", "answers": ["Promouvoir la recherche, les technologies et les applications spatiales", "Construire des avions", "Exploiter des a\u00e9roports", "Fournir des pr\u00e9visions m\u00e9t\u00e9orologiques"], "correct": 0, "fact": "L\u2019objectif de l\u2019ESA est de mettre en place et de promouvoir, \u00e0 des fins exclusivement pacifiques, la coop\u00e9ration entre les \u00c9tats europ\u00e9ens dans le domaine de la recherche et des technologies spatiales."}, {"question": "Qu\u2019est-ce que l\u2019ESA ?", "answers": ["Une universit\u00e9", "Une organisation europ\u00e9enne", "Une entreprise priv\u00e9e", "Une compagnie a\u00e9rienne"], "correct": 0, "fact": "ESA signifie Agence spatiale europ\u00e9enne, une organisation internationale d\u00e9di\u00e9e au d\u00e9veloppement des capacit\u00e9s spatiales de l\u2019Europe et \u00e0 la poursuite d\u2019investissements dans l\u2019espace qui apportent des b\u00e9n\u00e9fices aux citoyens d\u2019Europe et du monde entier."}, {"question": "L\u2019ESA travaille-t-elle avec des astronautes ?", "answers": ["Oui, avec des astronautes de l\u2019ESA", "Non, mais elle travaille avec des pilotes", "Oui, mais uniquement avec des astronautes de la NASA", "Non, elle travaille uniquement avec des scientifiques sur Terre"], "correct": 0, "fact": "L\u2019ESA forme et entretient une \u00e9quipe d\u2019astronautes venant de diff\u00e9rents pays europ\u00e9ens pour explorer l\u2019espace."}, {"question": "Lequel est un domaine d\u2019activit\u00e9 de l\u2019ESA ?", "answers": ["Technologies spatiales", "Design de mode", "Production alimentaire", "Transport routier"], "correct": 0, "fact": "L\u2019objectif de l\u2019ESA est de mettre en place et de promouvoir, \u00e0 des fins exclusivement pacifiques, la coop\u00e9ration entre les \u00c9tats europ\u00e9ens dans le domaine de la recherche et des technologies spatiales."}], "\u20ac200": [{"question": "Quelle plan\u00e8te est connue sous le nom de \u00ab plan\u00e8te rouge \u00bb ?", "answers": ["V\u00e9nus", "Mars", "Jupiter", "Mercure"], "correct": 1, "fact": "Mars para\u00eet rouge\u00e2tre parce que les min\u00e9raux de fer pr\u00e9sents dans son sol se sont oxyd\u00e9s, dans un processus comparable \u00e0 la formation de la rouille."}, {"question": "Quelle est la plus grande plan\u00e8te de notre Syst\u00e8me solaire ?", "answers": ["La Terre", "Saturne", "Jupiter", "Neptune"], "correct": 2, "fact": "Jupiter est la plus grande plan\u00e8te du Syst\u00e8me solaire, avec un diam\u00e8tre plus de 11 fois sup\u00e9rieur \u00e0 celui de la Terre."}, {"question": "Quelle plan\u00e8te est c\u00e9l\u00e8bre pour son syst\u00e8me d\u2019anneaux bien visible ?", "answers": ["Mars", "Saturne", "V\u00e9nus", "Mercure"], "correct": 1, "fact": "Les anneaux de Saturne sont principalement constitu\u00e9s d\u2019innombrables morceaux de glace et de mat\u00e9riaux rocheux."}, {"question": "Quelle plan\u00e8te est la plus proche du Soleil ?", "answers": ["V\u00e9nus", "La Terre", "Mercure", "Mars"], "correct": 2, "fact": "Mercure est la plan\u00e8te la plus proche du Soleil et effectue une orbite autour de celui-ci en environ 88 jours terrestres."}, {"question": "Quelle plan\u00e8te est parfois appel\u00e9e la plan\u00e8te s\u0153ur de la Terre en raison de sa taille similaire ?", "answers": ["Jupiter", "V\u00e9nus", "Mars", "Neptune"], "correct": 1, "fact": "V\u00e9nus est similaire \u00e0 la Terre par sa taille et sa composition, bien que son environnement de surface soit extr\u00eamement diff\u00e9rent."}, {"question": "Quel est le nom de la galaxie qui contient notre Syst\u00e8me solaire ?", "answers": ["Androm\u00e8de", "La Voie lact\u00e9e", "La galaxie du Tourbillon", "Le Sombrero"], "correct": 1, "fact": "Notre Syst\u00e8me solaire se trouve dans la Voie lact\u00e9e, une galaxie spirale barr\u00e9e qui contient des centaines de milliards d\u2019\u00e9toiles."}], "\u20ac500": [{"question": "\u00c0 quoi servent principalement les satellites d\u2019observation de la Terre ?", "answers": ["Uniquement aux pr\u00e9visions m\u00e9t\u00e9orologiques", "\u00c0 surveiller la Terre et les changements environnementaux", "Uniquement \u00e0 diffuser la t\u00e9l\u00e9vision", "\u00c0 prendre des photos de vacances"], "correct": 1, "fact": "Les donn\u00e9es satellitaires peuvent aider \u00e0 surveiller les for\u00eats, la banquise, la qualit\u00e9 de l\u2019air, les inondations, les incendies, les cultures et de nombreux autres changements sur notre plan\u00e8te."}, {"question": "Que peuvent aider les satellites \u00e0 surveiller sur de vastes zones ?", "answers": ["Les changements dans les for\u00eats", "Uniquement des maisons individuelles", "Uniquement des grottes souterraines", "Rien \u00e0 la surface de la Terre"], "correct": 0, "fact": "Les satellites d\u2019observation de la Terre peuvent surveiller \u00e0 plusieurs reprises de vastes zones, ce qui aide \u00e0 suivre les changements dans les for\u00eats, l\u2019agriculture et les \u00e9cosyst\u00e8mes."}, {"question": "Pourquoi les satellites sont-ils utiles pour observer les r\u00e9gions \u00e9loign\u00e9es de la Terre ?", "answers": ["Ils peuvent observer de vastes zones depuis l\u2019orbite", "Ils n\u2019ont jamais besoin d\u2019instruments", "Ils ne fonctionnent qu\u2019au-dessus des villes", "Ils remplacent toutes les mesures au sol"], "correct": 0, "fact": "Les satellites peuvent fournir des observations r\u00e9p\u00e9t\u00e9es de lieux difficiles ou dangereux \u00e0 atteindre depuis le sol."}, {"question": "Quel \u00e9v\u00e9nement les satellites d\u2019observation de la Terre peuvent-ils aider \u00e0 surveiller ?", "answers": ["Les inondations", "Uniquement les \u00e9clipses solaires", "Uniquement les pluies de m\u00e9t\u00e9ores", "Uniquement les lancements spatiaux"], "correct": 0, "fact": "Les observations satellitaires peuvent aider \u00e0 cartographier les zones inond\u00e9es et \u00e0 surveiller la situation avant, pendant et apr\u00e8s les grandes inondations."}, {"question": "Lequel de ces ph\u00e9nom\u00e8nes les observations satellitaires peuvent-elles aider \u00e0 surveiller dans l\u2019oc\u00e9an ?", "answers": ["L\u2019\u00e9tendue de la banquise", "Uniquement les poissons dans des filets individuels", "Uniquement les navires dans les ports", "Rien"], "correct": 0, "fact": "Les observations satellitaires peuvent suivre la banquise ainsi que de nombreux autres changements \u00e0 grande \u00e9chelle dans les oc\u00e9ans et les zones c\u00f4ti\u00e8res."}, {"question": "Quel est l\u2019un des avantages de l\u2019observation de la Terre depuis l\u2019espace ?", "answers": ["Une couverture mondiale ou r\u00e9gionale", "Aucun traitement des donn\u00e9es n\u2019est n\u00e9cessaire", "Les nuages ne peuvent jamais affecter les observations", "Chaque satellite voit tout"], "correct": 0, "fact": "Diff\u00e9rents instruments satellitaires offrent une large couverture et des mesures r\u00e9p\u00e9t\u00e9es qui compl\u00e8tent les observations effectu\u00e9es depuis le sol."}], "\u20ac1,200": [{"question": "Quel est le nom de la famille europ\u00e9enne de missions d\u2019observation de la Terre utilis\u00e9e par le programme Copernicus ?", "answers": ["Galileo", "Sentinel", "Voyager", "Kepler"], "correct": 1, "fact": "Les missions Sentinel agissent comme diff\u00e9rents ensembles d\u2019yeux. Certaines utilisent le radar, tandis que d\u2019autres observent les terres, les oc\u00e9ans ou l\u2019atmosph\u00e8re."}, {"question": "Quelle mission Sentinel de Copernicus utilise le radar pour observer la Terre ?", "answers": ["Sentinel-1", "Sentinel-6", "Sentinel-5P", "Sentinel-2"], "correct": 0, "fact": "Sentinel-1 utilise le radar, ce qui lui permet d\u2019observer la surface de la Terre de jour comme de nuit et \u00e0 travers la couverture nuageuse."}, {"question": "Quelle mission Sentinel est particuli\u00e8rement associ\u00e9e \u00e0 l\u2019imagerie d\u00e9taill\u00e9e des surfaces terrestres ?", "answers": ["Sentinel-2", "Sentinel-3", "Sentinel-5P", "Sentinel-6"], "correct": 0, "fact": "Sentinel-2 fournit des images optiques \u00e0 haute r\u00e9solution utiles pour \u00e9tudier la v\u00e9g\u00e9tation, l\u2019occupation des sols et de nombreuses autres caract\u00e9ristiques de la surface."}, {"question": "Qu\u2019est-ce que Copernicus ?", "answers": ["Le programme europ\u00e9en d\u2019observation de la Terre", "Un rover martien", "Un type de moteur-fus\u00e9e", "Un catalogue d\u2019\u00e9toiles"], "correct": 0, "fact": "Copernicus est le programme d\u2019observation de la Terre de l\u2019Union europ\u00e9enne, qui utilise des satellites et d\u2019autres sources pour fournir des informations environnementales."}, {"question": "Pourquoi les satellites radar peuvent-ils \u00eatre utiles par temps nuageux ?", "answers": ["Le radar peut observer \u00e0 travers les nuages dans de nombreuses situations", "Le radar transforme les nuages en ciel d\u00e9gag\u00e9", "Le radar ne fonctionne qu\u2019\u00e0 l\u2019int\u00e9rieur", "Le radar ne peut pas d\u00e9tecter la surface de la Terre"], "correct": 0, "fact": "Le radar \u00e0 synth\u00e8se d\u2019ouverture peut recueillir des observations ind\u00e9pendamment de la lumi\u00e8re du jour et peut souvent voir \u00e0 travers la couverture nuageuse."}, {"question": "Quel type d\u2019informations les missions Sentinel peuvent-elles fournir ?", "answers": ["Des observations des terres, des oc\u00e9ans et de l\u2019atmosph\u00e8re", "Uniquement des photographies d\u2019astronautes", "Uniquement des \u00e9missions radio", "Uniquement des observations de la Lune"], "correct": 0, "fact": "Les diff\u00e9rentes missions Sentinel sont con\u00e7ues pour effectuer diff\u00e9rentes mesures environnementales, couvrant les terres, les oc\u00e9ans et l\u2019atmosph\u00e8re."}], "\u20ac2,000": [{"question": "Quelle mission de l\u2019ESA a d\u00e9pos\u00e9 l\u2019atterrisseur Philae sur une com\u00e8te en 2014 ?", "answers": ["Gaia", "Rosetta", "Euclid", "Solar Orbiter"], "correct": 1, "fact": "Philae a rebondi apr\u00e8s son premier contact avec la com\u00e8te 67P. Dans la gravit\u00e9 extr\u00eamement faible de la com\u00e8te, m\u00eame un l\u00e9ger rebond est devenu un voyage spectaculaire."}, {"question": "Quel \u00e9tait le nom de la com\u00e8te visit\u00e9e par la mission Rosetta de l\u2019ESA ?", "answers": ["Halley", "67P/Churyumov-Gerasimenko", "Hale-Bopp", "Shoemaker-Levy 9"], "correct": 1, "fact": "Rosetta a voyag\u00e9 jusqu\u2019\u00e0 la com\u00e8te 67P/Churyumov-Gerasimenko et l\u2019a \u00e9tudi\u00e9e en l\u2019orbite pendant plus de deux ans."}, {"question": "Qu\u2019\u00e9tait Philae ?", "answers": ["Un atterrisseur", "Un t\u00e9lescope", "Une fus\u00e9e", "Un satellite de t\u00e9l\u00e9communications"], "correct": 0, "fact": "Philae \u00e9tait un petit atterrisseur robotis\u00e9 transport\u00e9 jusqu\u2019\u00e0 la com\u00e8te 67P par la sonde Rosetta de l\u2019ESA."}, {"question": "Qu\u2019est-ce qui rend particuli\u00e8rement difficile l\u2019atterrissage sur une petite com\u00e8te ?", "answers": ["Une gravit\u00e9 tr\u00e8s faible", "Trop d\u2019oxyg\u00e8ne", "Une atmosph\u00e8re \u00e9paisse", "De forts courants oc\u00e9aniques"], "correct": 0, "fact": "Une petite com\u00e8te poss\u00e8de une gravit\u00e9 extr\u00eamement faible, ce qui rend difficile pour un atterrisseur de rester fix\u00e9 \u00e0 sa surface."}, {"question": "Combien d\u2019astronautes de l\u2019ESA sont all\u00e9s dans l\u2019espace de septembre 2021 \u00e0 septembre 2026 ?", "answers": ["6", "20", "1", "Aucun"], "correct": 0, "fact": "Depuis la cr\u00e9ation de l\u2019ESA, un total de 27 astronautes diff\u00e9rents ont voyag\u00e9 dans l\u2019espace depuis diff\u00e9rents pays europ\u00e9ens."}, {"question": "Quel \u00e9tait un objectif scientifique majeur de Rosetta ?", "answers": ["\u00c9tudier une com\u00e8te en d\u00e9tail", "Faire atterrir des humains sur Mars", "Cartographier les oc\u00e9ans de la Terre", "Observer les p\u00f4les du Soleil"], "correct": 0, "fact": "Rosetta a \u00e9tudi\u00e9 la composition, la structure et l\u2019activit\u00e9 de la com\u00e8te 67P afin d\u2019am\u00e9liorer notre compr\u00e9hension des com\u00e8tes et du Syst\u00e8me solaire primitif."}], "\u20ac4,000": [{"question": "La mission Gaia de l\u2019ESA a \u00e9t\u00e9 con\u00e7ue pour cr\u00e9er une carte extr\u00eamement pr\u00e9cise de quoi ?", "answers": ["Des oc\u00e9ans de la Terre", "Des crat\u00e8res de la Lune", "De la galaxie de la Voie lact\u00e9e", "Des volcans de Mars"], "correct": 2, "fact": "En mesurant les positions et les mouvements des \u00e9toiles, Gaia aide les astronomes \u00e0 \u00e9tudier l\u2019histoire et la structure de notre galaxie."}, {"question": "Que mesure Gaia avec une tr\u00e8s grande pr\u00e9cision pour les \u00e9toiles ?", "answers": ["Leurs positions et leurs mouvements", "Leur odeur", "Uniquement leur temp\u00e9rature de surface", "Leurs pr\u00e9visions m\u00e9t\u00e9orologiques"], "correct": 0, "fact": "Les mesures astrom\u00e9triques de Gaia r\u00e9v\u00e8lent la position des \u00e9toiles et la fa\u00e7on dont elles se d\u00e9placent dans la Voie lact\u00e9e."}, {"question": "Quel type d\u2019objet Gaia observe-t-elle principalement ?", "answers": ["Les \u00e9toiles", "Les volcans", "Les nuages", "Les oc\u00e9ans"], "correct": 0, "fact": "Gaia a \u00e9t\u00e9 con\u00e7ue pour observer un nombre immense d\u2019\u00e9toiles et \u00e9tablir une image tridimensionnelle pr\u00e9cise de la Voie lact\u00e9e."}, {"question": "Pourquoi les mouvements stellaires sont-ils utiles aux astronomes ?", "answers": ["Ils r\u00e9v\u00e8lent des informations sur la structure et l\u2019histoire de la Voie lact\u00e9e", "Ils pr\u00e9disent la m\u00e9t\u00e9o terrestre", "Ils contr\u00f4lent directement les engins spatiaux", "Ils cr\u00e9ent de nouvelles \u00e9toiles"], "correct": 0, "fact": "Les positions et les mouvements des \u00e9toiles contiennent des indices sur la formation et l\u2019\u00e9volution de notre galaxie."}, {"question": "Quelle partie du spectre \u00e9lectromagn\u00e9tique Gaia utilise-t-elle pour ses principales mesures astrom\u00e9triques ?", "answers": ["La lumi\u00e8re visible", "Uniquement les ondes radio", "Uniquement les rayons X", "Uniquement les rayons gamma"], "correct": 0, "fact": "Gaia fonctionne principalement comme une mission d\u2019astrom\u00e9trie optique, mesurant les positions et les mouvements des \u00e9toiles avec une pr\u00e9cision extraordinaire."}, {"question": "Que peut aider les scientifiques \u00e0 \u00e9tudier une carte d\u00e9taill\u00e9e de la Voie lact\u00e9e ?", "answers": ["La formation et l\u2019\u00e9volution de la galaxie", "La m\u00e9t\u00e9o exacte de demain", "Les mar\u00e9es oc\u00e9aniques sur Jupiter", "La couleur des nuages terrestres"], "correct": 0, "fact": "Une carte stellaire pr\u00e9cise aide les chercheurs \u00e0 reconstituer la structure, la dynamique et l\u2019histoire de notre galaxie."}], "\u20ac8,000": [{"question": "Quelle mission dirig\u00e9e par l\u2019ESA \u00e9tudie le Soleil et est con\u00e7ue pour observer ses r\u00e9gions polaires ?", "answers": ["Solar Orbiter", "JUICE", "Hera", "BepiColombo"], "correct": 0, "fact": "Les p\u00f4les du Soleil sont difficiles \u00e0 voir depuis la Terre. Solar Orbiter utilise des survols plan\u00e9taires pour incliner son orbite et obtenir une meilleure vue."}, {"question": "Qu\u2019est-ce que Solar Orbiter est con\u00e7ue pour \u00e9tudier ?", "answers": ["Le Soleil", "Les lunes de Jupiter", "Uniquement les com\u00e8tes", "Uniquement les glaciers terrestres"], "correct": 0, "fact": "Solar Orbiter \u00e9tudie le Soleil et le vent solaire, aidant les scientifiques \u00e0 comprendre le fonctionnement de notre \u00e9toile."}, {"question": "Pourquoi Solar Orbiter utilise-t-elle des survols plan\u00e9taires ?", "answers": ["Pour modifier et incliner son orbite", "Pour se ravitailler en lumi\u00e8re solaire", "Pour atterrir sur une plan\u00e8te", "Pour recueillir des roches sur Terre"], "correct": 0, "fact": "Les assistances gravitationnelles des plan\u00e8tes peuvent modifier la trajectoire d\u2019un engin spatial et aider Solar Orbiter \u00e0 atteindre une orbite \u00e0 inclinaison plus \u00e9lev\u00e9e."}, {"question": "Qu\u2019est-ce que le vent solaire ?", "answers": ["Un flux de particules charg\u00e9es provenant du Soleil", "Le vent dans l\u2019atmosph\u00e8re terrestre", "Un courant d\u2019eau sur Mars", "Un anneau autour de Saturne"], "correct": 0, "fact": "Le vent solaire est un flux continu de particules charg\u00e9es qui s\u2019\u00e9chappent de l\u2019atmosph\u00e8re externe du Soleil."}, {"question": "Quelle caract\u00e9ristique du Soleil est particuli\u00e8rement importante pour comprendre son activit\u00e9 magn\u00e9tique ?", "answers": ["Son champ magn\u00e9tique", "Ses anneaux", "Ses oc\u00e9ans", "Sa surface solide"], "correct": 0, "fact": "Le champ magn\u00e9tique du Soleil est \u00e0 l\u2019origine de nombreuses formes d\u2019activit\u00e9 solaire, notamment les taches solaires et les \u00e9ruptions solaires."}, {"question": "Qu\u2019est-ce qui rend difficile l\u2019observation des r\u00e9gions polaires du Soleil depuis la Terre ?", "answers": ["La g\u00e9om\u00e9trie d\u2019observation", "La Lune les bloque chaque jour", "Le Soleil n\u2019a pas de p\u00f4les", "Elles se trouvent derri\u00e8re Saturne"], "correct": 0, "fact": "Depuis le point de vue habituel de la Terre, les p\u00f4les du Soleil sont vus sous un angle tr\u00e8s faible ; un engin spatial dot\u00e9 d\u2019une orbite inclin\u00e9e peut donc offrir une nouvelle perspective pr\u00e9cieuse."}], "\u20ac16,000": [{"question": "Que peuvent d\u00e9tecter les satellites Copernicus Sentinel en Antarctique ?", "answers": ["Des dinosaures marchant sous la glace", "Des changements dans l\u2019\u00e9paisseur et le mouvement de la glace", "Des messages radio extraterrestres", "Des volcans sur Mars"], "correct": 1, "fact": "Les satellites radar peuvent observer la glace m\u00eame \u00e0 travers les nuages et pendant la longue nuit polaire, ce qui en fait des outils pr\u00e9cieux pour suivre les changements."}, {"question": "Pourquoi le radar est-il particuli\u00e8rement utile pour observer l\u2019Antarctique ?", "answers": ["Il peut fonctionner sans lumi\u00e8re du Soleil et \u00e0 travers la couverture nuageuse", "Il fait fondre la glace", "Il ne fonctionne qu\u2019\u00e0 midi", "Il a toujours besoin d\u2019un ciel d\u00e9gag\u00e9"], "correct": 0, "fact": "Les instruments radar peuvent recueillir des observations dans l\u2019obscurit\u00e9 et d\u00e9pendent beaucoup moins de conditions sans nuages que les instruments optiques."}, {"question": "Que peuvent r\u00e9v\u00e9ler les observations satellitaires sur les glaciers ?", "answers": ["Les changements dans leur mouvement", "Leur go\u00fbt", "L\u2019\u00e2ge exact de chaque flocon de neige", "Leur temp\u00e9rature interne partout"], "correct": 0, "fact": "Des observations satellitaires r\u00e9p\u00e9t\u00e9es peuvent montrer \u00e0 quelle vitesse les glaciers et les courants de glace se d\u00e9placent et comment ces mouvements \u00e9voluent au fil du temps."}, {"question": "Qu\u2019est-ce qu\u2019une calotte glaciaire ?", "answers": ["Une vaste masse de glace terrestre couvrant une grande superficie", "Une couche d\u2019eau de mer", "Une formation nuageuse", "Une coul\u00e9e de lave volcanique"], "correct": 0, "fact": "Les calottes glaciaires de l\u2019Antarctique et du Groenland sont d\u2019immenses masses de glace terrestre qui contiennent la majeure partie de la glace d\u2019eau douce de la Terre."}, {"question": "Quel type de changement un radar satellitaire peut-il d\u00e9tecter \u00e0 la surface de la glace ?", "answers": ["Le mouvement et la d\u00e9formation", "Uniquement la couleur", "Uniquement la temp\u00e9rature de l\u2019air", "Uniquement l\u2019\u00e2ge de la glace"], "correct": 0, "fact": "Les mesures radar peuvent \u00eatre utilis\u00e9es pour d\u00e9tecter les mouvements et les d\u00e9formations de surface, notamment les changements dans les glaciers et les calottes glaciaires."}, {"question": "Pourquoi est-il important pour les sciences de la Terre de surveiller la glace de l\u2019Antarctique ?", "answers": ["Cela aide \u00e0 suivre les changements dans l\u2019environnement polaire", "Cela d\u00e9termine le nombre d\u2019\u00e9toiles dans la Voie lact\u00e9e", "Cela mesure l\u2019atmosph\u00e8re de Jupiter", "Cela remplace tous les mod\u00e8les climatiques"], "correct": 0, "fact": "Les observations \u00e0 long terme de la glace antarctique aident les scientifiques \u00e0 comprendre les changements dans l\u2019environnement polaire et leurs effets \u00e0 plus grande \u00e9chelle."}], "\u20ac24,000": [{"question": "Que signifie le nom JUICE ?", "answers": ["Jupiter Investigation of Comets and Exploration", "Joint Universe Ice and Climate Explorer", "Jupiter Icy Moons Explorer", "Journey Into Cosmic Evolution"], "correct": 2, "fact": "JUICE voyage vers le syst\u00e8me de Jupiter pour \u00e9tudier la plan\u00e8te g\u00e9ante et ses lunes glac\u00e9es abritant des oc\u00e9ans."}, {"question": "Quelle plan\u00e8te JUICE voyage-t-elle \u00e9tudier ?", "answers": ["Mars", "Jupiter", "Saturne", "V\u00e9nus"], "correct": 1, "fact": "JUICE est l\u2019explorateur des lunes glac\u00e9es de Jupiter de l\u2019ESA et est con\u00e7u pour \u00e9tudier Jupiter et plusieurs de ses grandes lunes glac\u00e9es."}, {"question": "Laquelle de ces lunes glac\u00e9es est \u00e9tudi\u00e9e par JUICE ?", "answers": ["Ganym\u00e8de", "Phobos", "Titan", "Triton"], "correct": 0, "fact": "JUICE \u00e9tudiera Ganym\u00e8de en d\u00e9tail et effectuera \u00e9galement des observations d\u2019Europe et de Callisto au cours de sa mission."}, {"question": "Qu\u2019est-ce qui est particuli\u00e8rement int\u00e9ressant \u00e0 propos des lunes glac\u00e9es de Jupiter ?", "answers": ["Certaines pourraient contenir des oc\u00e9ans souterrains", "Elles ont toutes l\u2019atmosph\u00e8re de la Terre", "Elles sont plus chaudes que le Soleil", "Elles sont enti\u00e8rement constitu\u00e9es de m\u00e9tal"], "correct": 0, "fact": "Les donn\u00e9es disponibles indiquent que certaines des lunes glac\u00e9es de Jupiter contiennent des oc\u00e9ans sous leur surface gel\u00e9e."}, {"question": "Quelle lune doit devenir la principale cible de la mission orbitale de JUICE ?", "answers": ["Ganym\u00e8de", "Io", "Europe", "Amalth\u00e9e"], "correct": 0, "fact": "JUICE doit se mettre en orbite autour de Ganym\u00e8de, ce qui en fera le premier engin spatial \u00e0 se mettre en orbite autour d\u2019une lune autre que celle de la Terre."}, {"question": "Pourquoi les lunes glac\u00e9es sont-elles int\u00e9ressantes dans la recherche d\u2019environnements potentiellement habitables ?", "answers": ["Elles pourraient contenir de l\u2019eau liquide sous leur glace", "Elles sont toutes proches du Soleil", "Elles poss\u00e8dent les continents de la Terre", "Elles sont constitu\u00e9es d\u2019oxyg\u00e8ne pur"], "correct": 0, "fact": "L\u2019eau liquide est l\u2019un des ingr\u00e9dients que les scientifiques consid\u00e8rent comme importants lorsqu\u2019ils \u00e9tudient des environnements susceptibles d\u2019abriter une forme de vie."}], "\u20ac44,000": [{"question": "Quelle mission ESA-JAXA utilise une s\u00e9rie complexe de survols plan\u00e9taires lors de son voyage vers Mercure ?", "answers": ["Euclid", "Sentinel-2", "BepiColombo", "Philae"], "correct": 2, "fact": "Atteindre Mercure est \u00e9tonnamment difficile. Un engin spatial doit perdre une grande quantit\u00e9 d\u2019\u00e9nergie orbitale ; BepiColombo utilise donc des survols comme des man\u0153uvres de guidage cosmiques soigneusement planifi\u00e9es."}, {"question": "Quelle plan\u00e8te est la destination principale de BepiColombo ?", "answers": ["Mercure", "Mars", "Jupiter", "V\u00e9nus"], "correct": 0, "fact": "BepiColombo est une mission conjointe de l\u2019ESA et de la JAXA con\u00e7ue pour \u00e9tudier Mercure, la plan\u00e8te la plus proche du Soleil."}, {"question": "Pourquoi atteindre Mercure est-il particuli\u00e8rement difficile pour un engin spatial lanc\u00e9 depuis la Terre ?", "answers": ["Il doit perdre de l\u2019\u00e9nergie orbitale pour se rapprocher du Soleil", "Mercure poss\u00e8de une atmosph\u00e8re \u00e9paisse", "Mercure est en dehors du Syst\u00e8me solaire", "Elle poss\u00e8de des oc\u00e9ans qui bloquent les engins spatiaux"], "correct": 0, "fact": "Un engin spatial voyageant depuis la Terre doit perdre une quantit\u00e9 importante d\u2019\u00e9nergie orbitale pour se placer sur une orbite proche du Soleil, ce qui fait de Mercure une destination exigeante."}, {"question": "Quand l\u2019ESA a-t-elle \u00e9t\u00e9 fond\u00e9e ?", "answers": ["1975", "1965", "1970", "1985"], "correct": 0, "fact": "La JAXA est l\u2019agence spatiale nationale et l\u2019organisme de recherche du Japon. BepiColombo est une collaboration entre la JAXA et l\u2019ESA."}, {"question": "O\u00f9 se trouve le si\u00e8ge de l\u2019ESA ?", "answers": ["Paris, France", "Berlin, Allemagne", "Rome, Italie", "Londres, Royaume-Uni"], "correct": 0, "fact": "L\u2019ESA compte 23 \u00c9tats membres et sept principaux \u00e9tablissements en Europe, son si\u00e8ge \u00e9tant situ\u00e9 au centre de Paris."}, {"question": "Quel est le plus grand \u00e9tablissement de l\u2019ESA ?", "answers": ["ESRIN, Italie", "ESTEC, aux Pays-Bas", "ESOC, Allemagne", "Si\u00e8ge de l\u2019ESA, France"], "correct": 1, "fact": "ESTEC est le Centre europ\u00e9en de recherche et de technologie spatiales, le c\u0153ur technique de l\u2019ESA, o\u00f9 la plupart des projets de l\u2019ESA voient le jour et sont accompagn\u00e9s \u00e0 travers les diff\u00e9rentes phases de leur d\u00e9veloppement."}]}, "es": {"\u20ac100": [{"question": "\u00bfQu\u00e9 significa ESA?", "answers": ["Alianza Europea de Ciencia", "Agencia Europea de Sat\u00e9lites", "Agencia Espacial Europea", "Asociaci\u00f3n Espacial de Europa"], "correct": 2, "fact": "La ESA re\u00fane a los pa\u00edses europeos para explorar el espacio y utilizar la tecnolog\u00eda espacial en beneficio de las personas en la Tierra."}, {"question": "Entre otras cosas, \u00bfqu\u00e9 estudia y explora principalmente la ESA?", "answers": ["Los oc\u00e9anos", "El espacio y la Tierra desde el espacio", "El subsuelo de la Tierra", "Todo lo anterior"], "correct": 3, "fact": "La ESA desarrolla y opera misiones espaciales que estudian la Tierra, incluida la composici\u00f3n y las estructuras de su subsuelo e interior, el Sistema Solar y el universo en general."}, {"question": "\u00bfCu\u00e1l es el prop\u00f3sito principal de la ESA?", "answers": ["Promover la investigaci\u00f3n, la tecnolog\u00eda y las aplicaciones espaciales", "Construir aviones", "Operar aeropuertos", "Proporcionar pron\u00f3sticos meteorol\u00f3gicos"], "correct": 0, "fact": "El prop\u00f3sito de la ESA es proporcionar y promover, exclusivamente con fines pac\u00edficos, la cooperaci\u00f3n entre los Estados europeos en investigaci\u00f3n y tecnolog\u00eda espaciales."}, {"question": "\u00bfQu\u00e9 es la ESA?", "answers": ["Una universidad", "Una organizaci\u00f3n europea", "Una empresa privada", "Una aerol\u00ednea"], "correct": 1, "fact": "ESA significa Agencia Espacial Europea, una organizaci\u00f3n internacional dedicada a impulsar el desarrollo de la capacidad espacial de Europa y a garantizar que la inversi\u00f3n en el espacio siga aportando beneficios a los ciudadanos de Europa y del mundo."}, {"question": "\u00bfTrabaja la ESA con astronautas?", "answers": ["S\u00ed, con astronautas de la ESA", "No, pero trabaja con pilotos", "S\u00ed, pero solo con astronautas de la NASA", "No, trabaja \u00fanicamente con cient\u00edficos en la Tierra"], "correct": 0, "fact": "La ESA forma y mantiene un equipo de astronautas procedentes de distintos pa\u00edses europeos para explorar el espacio."}, {"question": "\u00bfCu\u00e1l es un \u00e1rea de trabajo de la ESA?", "answers": ["Tecnolog\u00eda espacial", "Dise\u00f1o de moda", "Producci\u00f3n de alimentos", "Transporte por carretera"], "correct": 0, "fact": "El prop\u00f3sito de la ESA es proporcionar y promover, exclusivamente con fines pac\u00edficos, la cooperaci\u00f3n entre los Estados europeos en investigaci\u00f3n y tecnolog\u00eda espaciales."}], "\u20ac200": [{"question": "\u00bfQu\u00e9 planeta es conocido como el \u00abPlaneta Rojo\u00bb?", "answers": ["Venus", "Marte", "J\u00fapiter", "Mercurio"], "correct": 1, "fact": "Marte se ve rojizo porque los minerales de hierro de su suelo se han oxidado, en un proceso parecido a la oxidaci\u00f3n del hierro."}, {"question": "\u00bfQu\u00e9 planeta es el m\u00e1s grande de nuestro Sistema Solar?", "answers": ["La Tierra", "Saturno", "J\u00fapiter", "Neptuno"], "correct": 2, "fact": "J\u00fapiter es el planeta m\u00e1s grande del Sistema Solar, con un di\u00e1metro m\u00e1s de 11 veces mayor que el de la Tierra."}, {"question": "\u00bfQu\u00e9 planeta es famoso por su destacado sistema de anillos?", "answers": ["Marte", "Saturno", "Venus", "Mercurio"], "correct": 1, "fact": "Los anillos de Saturno est\u00e1n formados principalmente por innumerables fragmentos de hielo y material rocoso."}, {"question": "\u00bfQu\u00e9 planeta est\u00e1 m\u00e1s cerca del Sol?", "answers": ["Venus", "La Tierra", "Mercurio", "Marte"], "correct": 2, "fact": "Mercurio es el planeta m\u00e1s interior y completa una \u00f3rbita alrededor del Sol en unos 88 d\u00edas terrestres."}, {"question": "\u00bfQu\u00e9 planeta se llama a veces el planeta hermano de la Tierra debido a su tama\u00f1o similar?", "answers": ["J\u00fapiter", "Venus", "Marte", "Neptuno"], "correct": 1, "fact": "Venus es similar a la Tierra en tama\u00f1o y composici\u00f3n, aunque las condiciones de su superficie son extremadamente diferentes."}, {"question": "\u00bfC\u00f3mo se llama la galaxia que contiene nuestro Sistema Solar?", "answers": ["Andr\u00f3meda", "La V\u00eda L\u00e1ctea", "Remolino", "Sombrero"], "correct": 1, "fact": "Nuestro Sistema Solar se encuentra en la V\u00eda L\u00e1ctea, una galaxia espiral barrada que contiene cientos de miles de millones de estrellas."}], "\u20ac500": [{"question": "\u00bfPara qu\u00e9 se utilizan principalmente los sat\u00e9lites de observaci\u00f3n de la Tierra?", "answers": ["Solo para pron\u00f3sticos meteorol\u00f3gicos", "Para vigilar la Tierra y los cambios ambientales", "Solo para transmitir televisi\u00f3n", "Para tomar fotograf\u00edas de vacaciones"], "correct": 1, "fact": "Los datos de los sat\u00e9lites pueden ayudar a vigilar bosques, hielo marino, calidad del aire, inundaciones, incendios, cultivos y muchos otros cambios en nuestro planeta."}, {"question": "\u00bfQu\u00e9 pueden ayudar a vigilar los sat\u00e9lites sobre grandes \u00e1reas?", "answers": ["Cambios en los bosques", "Solo casas individuales", "Solo cuevas subterr\u00e1neas", "Nada en la superficie terrestre"], "correct": 0, "fact": "Los sat\u00e9lites de observaci\u00f3n de la Tierra pueden estudiar repetidamente grandes \u00e1reas, ayudando a seguir los cambios en los bosques, la agricultura y los ecosistemas."}, {"question": "\u00bfPor qu\u00e9 son \u00fatiles los sat\u00e9lites para observar zonas remotas de la Tierra?", "answers": ["Pueden observar grandes \u00e1reas desde la \u00f3rbita", "Nunca necesitan instrumentos", "Solo funcionan sobre ciudades", "Sustituyen todas las mediciones terrestres"], "correct": 0, "fact": "Los sat\u00e9lites pueden proporcionar observaciones repetidas de lugares a los que es dif\u00edcil o peligroso llegar desde tierra."}, {"question": "\u00bfQu\u00e9 fen\u00f3meno pueden ayudar a vigilar los sat\u00e9lites de observaci\u00f3n de la Tierra?", "answers": ["Inundaciones", "Solo eclipses solares", "Solo lluvias de meteoros", "Solo lanzamientos de naves espaciales"], "correct": 0, "fact": "Las observaciones por sat\u00e9lite pueden ayudar a cartografiar las zonas inundadas y a vigilar la situaci\u00f3n antes, durante y despu\u00e9s de grandes inundaciones."}, {"question": "\u00bfCu\u00e1l de estos fen\u00f3menos pueden ayudar a vigilar las observaciones por sat\u00e9lite en el oc\u00e9ano?", "answers": ["La extensi\u00f3n del hielo marino", "Solo peces dentro de redes individuales", "Solo barcos en los puertos", "Nada"], "correct": 0, "fact": "Las observaciones por sat\u00e9lite pueden seguir el hielo marino y muchos otros cambios a gran escala en los oc\u00e9anos y las zonas costeras."}, {"question": "\u00bfCu\u00e1l es una ventaja de observar la Tierra desde el espacio?", "answers": ["Cobertura global o regional", "No es necesario procesar los datos", "Las nubes nunca pueden afectar a las observaciones", "Cada sat\u00e9lite lo ve todo"], "correct": 0, "fact": "Los distintos instrumentos satelitales proporcionan una amplia cobertura y mediciones repetidas que complementan las observaciones realizadas desde tierra."}], "\u20ac1,200": [{"question": "\u00bfC\u00f3mo se llama la familia europea de misiones de observaci\u00f3n de la Tierra utilizada por el programa Copernicus?", "answers": ["Galileo", "Sentinel", "Voyager", "Kepler"], "correct": 1, "fact": "Las misiones Sentinel funcionan como diferentes conjuntos de ojos. Algunas utilizan radar, mientras que otras observan la tierra, los oc\u00e9anos o la atm\u00f3sfera."}, {"question": "\u00bfQu\u00e9 misi\u00f3n Copernicus Sentinel utiliza radar para observar la Tierra?", "answers": ["Sentinel-1", "Sentinel-6", "Sentinel-5P", "Sentinel-2"], "correct": 0, "fact": "Sentinel-1 utiliza radar, lo que le permite observar la superficie terrestre de d\u00eda y de noche y a trav\u00e9s de la cobertura nubosa."}, {"question": "\u00bfQu\u00e9 misi\u00f3n Sentinel est\u00e1 especialmente asociada con im\u00e1genes detalladas de la superficie terrestre?", "answers": ["Sentinel-2", "Sentinel-3", "Sentinel-5P", "Sentinel-6"], "correct": 0, "fact": "Sentinel-2 proporciona im\u00e1genes \u00f3pticas de alta resoluci\u00f3n \u00fatiles para estudiar la vegetaci\u00f3n, la cobertura del suelo y muchas otras caracter\u00edsticas de la superficie."}, {"question": "\u00bfQu\u00e9 es Copernicus?", "answers": ["El programa europeo de observaci\u00f3n de la Tierra", "Un veh\u00edculo explorador de Marte", "Un tipo de motor de cohete", "Un cat\u00e1logo de estrellas"], "correct": 0, "fact": "Copernicus es el programa de observaci\u00f3n de la Tierra de la Uni\u00f3n Europea, que utiliza sat\u00e9lites y otras fuentes para proporcionar informaci\u00f3n medioambiental."}, {"question": "\u00bfPor qu\u00e9 pueden ser \u00fatiles los sat\u00e9lites de radar durante el tiempo nublado?", "answers": ["El radar puede observar a trav\u00e9s de las nubes en muchas situaciones", "El radar convierte las nubes en cielos despejados", "El radar solo funciona en interiores", "El radar no puede detectar la superficie terrestre"], "correct": 0, "fact": "El radar de apertura sint\u00e9tica puede recopilar observaciones independientemente de la luz del d\u00eda y a menudo puede ver a trav\u00e9s de la cobertura nubosa."}, {"question": "\u00bfQu\u00e9 tipo de informaci\u00f3n pueden proporcionar las misiones Sentinel?", "answers": ["Observaciones de la tierra, los oc\u00e9anos y la atm\u00f3sfera", "Solo fotograf\u00edas de astronautas", "Solo transmisiones de radio", "Solo observaciones de la Luna"], "correct": 0, "fact": "Las distintas misiones Sentinel est\u00e1n dise\u00f1adas para diferentes mediciones ambientales y cubren la tierra, los oc\u00e9anos y la atm\u00f3sfera."}], "\u20ac2,000": [{"question": "\u00bfQu\u00e9 misi\u00f3n de la ESA deposit\u00f3 el m\u00f3dulo de aterrizaje Philae en un cometa en 2014?", "answers": ["Gaia", "Rosetta", "Euclid", "Solar Orbiter"], "correct": 1, "fact": "Philae rebot\u00f3 despu\u00e9s de su primer contacto con el cometa 67P. Debido a la gravedad extremadamente d\u00e9bil del cometa, incluso un rebote suave se convirti\u00f3 en un viaje espectacular."}, {"question": "\u00bfC\u00f3mo se llamaba el cometa visitado por la misi\u00f3n Rosetta de la ESA?", "answers": ["Halley", "67P/Churyumov-Gerasimenko", "Hale-Bopp", "Shoemaker-Levy 9"], "correct": 1, "fact": "Rosetta viaj\u00f3 hasta el cometa 67P/Churyumov-Gerasimenko y lo estudi\u00f3, orbit\u00e1ndolo durante m\u00e1s de dos a\u00f1os."}, {"question": "\u00bfQu\u00e9 era Philae?", "answers": ["Un m\u00f3dulo de aterrizaje", "Un telescopio", "Un cohete", "Un sat\u00e9lite de comunicaciones"], "correct": 0, "fact": "Philae era un peque\u00f1o m\u00f3dulo de aterrizaje rob\u00f3tico que la nave espacial Rosetta de la ESA llev\u00f3 hasta el cometa 67P."}, {"question": "\u00bfQu\u00e9 hace que aterrizar en un cometa peque\u00f1o sea especialmente dif\u00edcil?", "answers": ["Una gravedad muy d\u00e9bil", "Demasiado ox\u00edgeno", "Una atm\u00f3sfera espesa", "Fuertes corrientes oce\u00e1nicas"], "correct": 0, "fact": "Un cometa peque\u00f1o tiene una gravedad extremadamente d\u00e9bil, lo que dificulta que un m\u00f3dulo de aterrizaje permanezca sujeto a la superficie."}, {"question": "\u00bfCu\u00e1ntos astronautas de la ESA viajaron al espacio desde septiembre de 2021 hasta septiembre de 2026?", "answers": ["6", "20", "1", "Ninguno"], "correct": 0, "fact": "Desde la fundaci\u00f3n de la ESA, un total de 27 astronautas individuales han viajado al espacio desde distintos pa\u00edses europeos."}, {"question": "\u00bfCu\u00e1l fue un objetivo cient\u00edfico importante de Rosetta?", "answers": ["Estudiar un cometa en detalle", "Llevar humanos a Marte", "Cartografiar los oc\u00e9anos de la Tierra", "Observar los polos del Sol"], "correct": 0, "fact": "Rosetta estudi\u00f3 la composici\u00f3n, la estructura y la actividad del cometa 67P para mejorar nuestra comprensi\u00f3n de los cometas y del Sistema Solar primitivo."}], "\u20ac4,000": [{"question": "La misi\u00f3n Gaia de la ESA fue dise\u00f1ada para crear un mapa extraordinariamente preciso de \u00bfqu\u00e9?", "answers": ["Los oc\u00e9anos de la Tierra", "Los cr\u00e1teres de la Luna", "La galaxia de la V\u00eda L\u00e1ctea", "Los volcanes de Marte"], "correct": 2, "fact": "Al medir las posiciones y los movimientos de las estrellas, Gaia ayuda a los astr\u00f3nomos a investigar la historia y la estructura de nuestra galaxia."}, {"question": "\u00bfQu\u00e9 mide Gaia con gran precisi\u00f3n en las estrellas?", "answers": ["Posiciones y movimientos", "Su olor", "Solo su temperatura superficial", "Sus pron\u00f3sticos meteorol\u00f3gicos"], "correct": 0, "fact": "Las mediciones astrom\u00e9tricas de Gaia revelan c\u00f3mo est\u00e1n situadas y c\u00f3mo se mueven las estrellas por la V\u00eda L\u00e1ctea."}, {"question": "\u00bfQu\u00e9 tipo de objeto observa principalmente Gaia?", "answers": ["Estrellas", "Volcanes", "Nubes", "Oc\u00e9anos"], "correct": 0, "fact": "Gaia fue dise\u00f1ada para observar enormes cantidades de estrellas y construir una imagen tridimensional precisa de la V\u00eda L\u00e1ctea."}, {"question": "\u00bfPor qu\u00e9 son \u00fatiles los movimientos estelares para los astr\u00f3nomos?", "answers": ["Revelan informaci\u00f3n sobre la estructura y la historia de la V\u00eda L\u00e1ctea", "Predicen el tiempo en la Tierra", "Controlan directamente las naves espaciales", "Crean nuevas estrellas"], "correct": 0, "fact": "Las posiciones y los movimientos de las estrellas contienen pistas sobre c\u00f3mo se form\u00f3 y evolucion\u00f3 nuestra galaxia."}, {"question": "\u00bfQu\u00e9 parte del espectro electromagn\u00e9tico utiliza Gaia para sus principales mediciones astrom\u00e9tricas?", "answers": ["Luz visible", "Solo ondas de radio", "Solo rayos X", "Solo rayos gamma"], "correct": 0, "fact": "Gaia funciona principalmente como una misi\u00f3n de astrometr\u00eda \u00f3ptica, midiendo las posiciones y los movimientos estelares con extraordinaria precisi\u00f3n."}, {"question": "\u00bfQu\u00e9 puede ayudar a investigar un mapa detallado de la V\u00eda L\u00e1ctea?", "answers": ["La formaci\u00f3n y evoluci\u00f3n de la galaxia", "El tiempo exacto de ma\u00f1ana", "Las mareas oce\u00e1nicas de J\u00fapiter", "El color de las nubes de la Tierra"], "correct": 0, "fact": "Un mapa estelar preciso ayuda a los investigadores a reconstruir la estructura, la din\u00e1mica y la historia de nuestra galaxia."}], "\u20ac8,000": [{"question": "\u00bfQu\u00e9 misi\u00f3n dirigida por la ESA estudia el Sol y est\u00e1 dise\u00f1ada para observar sus regiones polares?", "answers": ["Solar Orbiter", "JUICE", "Hera", "BepiColombo"], "correct": 0, "fact": "Los polos del Sol son dif\u00edciles de ver desde la Tierra. Solar Orbiter utiliza sobrevuelos planetarios para inclinar su \u00f3rbita y obtener una mejor vista."}, {"question": "\u00bfQu\u00e9 est\u00e1 dise\u00f1ada para estudiar Solar Orbiter?", "answers": ["El Sol", "Las lunas de J\u00fapiter", "Solo los cometas", "Solo los glaciares de la Tierra"], "correct": 0, "fact": "Solar Orbiter estudia el Sol y el viento solar, ayudando a los cient\u00edficos a comprender c\u00f3mo funciona nuestra estrella."}, {"question": "\u00bfPor qu\u00e9 utiliza Solar Orbiter sobrevuelos planetarios?", "answers": ["Para cambiar e inclinar su \u00f3rbita", "Para repostar con luz solar", "Para aterrizar en un planeta", "Para recoger rocas de la Tierra"], "correct": 0, "fact": "Las asistencias gravitatorias de los planetas pueden cambiar la trayectoria de una nave espacial y ayudar a Solar Orbiter a obtener una \u00f3rbita con mayor inclinaci\u00f3n."}, {"question": "\u00bfQu\u00e9 es el viento solar?", "answers": ["Un flujo de part\u00edculas cargadas procedentes del Sol", "El viento de la atm\u00f3sfera terrestre", "Una corriente de agua en Marte", "Un anillo alrededor de Saturno"], "correct": 0, "fact": "El viento solar es un flujo continuo de part\u00edculas cargadas que escapan de la atm\u00f3sfera exterior del Sol."}, {"question": "\u00bfQu\u00e9 caracter\u00edstica del Sol es especialmente importante para comprender su actividad magn\u00e9tica?", "answers": ["Su campo magn\u00e9tico", "Sus anillos", "Sus oc\u00e9anos", "Su superficie s\u00f3lida"], "correct": 0, "fact": "El campo magn\u00e9tico del Sol impulsa muchas formas de actividad solar, incluidas las manchas solares y las erupciones solares."}, {"question": "\u00bfQu\u00e9 dificulta la observaci\u00f3n de las regiones polares del Sol desde la Tierra?", "answers": ["La geometr\u00eda de observaci\u00f3n", "La Luna las bloquea todos los d\u00edas", "El Sol no tiene polos", "Est\u00e1n detr\u00e1s de Saturno"], "correct": 0, "fact": "Desde el punto de vista habitual de la Tierra, los polos del Sol se observan con un \u00e1ngulo muy peque\u00f1o, por lo que una nave espacial con una \u00f3rbita inclinada puede proporcionar una nueva perspectiva valiosa."}], "\u20ac16,000": [{"question": "\u00bfQu\u00e9 pueden detectar los sat\u00e9lites Copernicus Sentinel en la Ant\u00e1rtida?", "answers": ["Dinosaurios caminando bajo el hielo", "Cambios en el espesor y el movimiento del hielo", "Mensajes de radio alien\u00edgenas", "Volcanes en Marte"], "correct": 1, "fact": "Los sat\u00e9lites de radar pueden observar el hielo incluso a trav\u00e9s de las nubes y durante la larga noche polar, lo que los convierte en herramientas valiosas para seguir los cambios."}, {"question": "\u00bfPor qu\u00e9 es especialmente \u00fatil el radar para observar la Ant\u00e1rtida?", "answers": ["Puede funcionar sin luz solar y a trav\u00e9s de la cobertura nubosa", "Derrite el hielo", "Solo funciona al mediod\u00eda", "Necesita cielos despejados en todo momento"], "correct": 0, "fact": "Los instrumentos de radar pueden recopilar observaciones en la oscuridad y dependen mucho menos de condiciones sin nubes que los instrumentos \u00f3pticos."}, {"question": "\u00bfQu\u00e9 pueden revelar las observaciones por sat\u00e9lite sobre los glaciares?", "answers": ["Cambios en su movimiento", "Su sabor", "La edad exacta de cada copo de nieve", "Su temperatura interna en todas partes"], "correct": 0, "fact": "Las observaciones repetidas por sat\u00e9lite pueden mostrar a qu\u00e9 velocidad se mueven los glaciares y las corrientes de hielo y c\u00f3mo cambian esos patrones con el tiempo."}, {"question": "\u00bfQu\u00e9 es una capa de hielo?", "answers": ["Una enorme masa de hielo terrestre que cubre una gran superficie", "Una capa de agua de mar", "Una formaci\u00f3n de nubes", "Un flujo de lava volc\u00e1nica"], "correct": 0, "fact": "Las capas de hielo de la Ant\u00e1rtida y Groenlandia son enormes masas de hielo terrestre que contienen la mayor parte del hielo de agua dulce del planeta."}, {"question": "\u00bfQu\u00e9 tipo de cambio puede detectar el radar de un sat\u00e9lite en una superficie de hielo?", "answers": ["Movimiento y deformaci\u00f3n", "Solo el color", "Solo la temperatura del aire", "Solo la edad del hielo"], "correct": 0, "fact": "Las mediciones de radar pueden utilizarse para detectar el movimiento y la deformaci\u00f3n de la superficie, incluidos los cambios en glaciares y capas de hielo."}, {"question": "\u00bfPor qu\u00e9 es importante para las ciencias de la Tierra vigilar el hielo ant\u00e1rtico?", "answers": ["Ayuda a seguir los cambios en el entorno polar", "Determina el n\u00famero de estrellas de la V\u00eda L\u00e1ctea", "Mide la atm\u00f3sfera de J\u00fapiter", "Sustituye todos los modelos clim\u00e1ticos"], "correct": 0, "fact": "Las observaciones a largo plazo del hielo ant\u00e1rtico ayudan a los cient\u00edficos a comprender los cambios en el entorno polar y sus efectos m\u00e1s amplios."}], "\u20ac24,000": [{"question": "\u00bfQu\u00e9 significa el nombre JUICE?", "answers": ["Investigaci\u00f3n de J\u00fapiter de cometas y exploraci\u00f3n", "Explorador conjunto del universo, el hielo y el clima", "Explorador de las lunas heladas de J\u00fapiter", "Viaje hacia la evoluci\u00f3n c\u00f3smica"], "correct": 2, "fact": "JUICE viaja al sistema de J\u00fapiter para estudiar el planeta gigante y sus lunas heladas que contienen oc\u00e9anos."}, {"question": "\u00bfQu\u00e9 planeta viajar\u00e1 a estudiar JUICE?", "answers": ["Marte", "J\u00fapiter", "Saturno", "Venus"], "correct": 1, "fact": "JUICE es el Explorador de las Lunas Heladas de J\u00fapiter de la ESA y est\u00e1 dise\u00f1ado para investigar J\u00fapiter y varias de sus grandes lunas heladas."}, {"question": "\u00bfCu\u00e1l de estas es una de las lunas heladas que estudiar\u00e1 JUICE?", "answers": ["Gan\u00edmedes", "Fobos", "Tit\u00e1n", "Trit\u00f3n"], "correct": 0, "fact": "JUICE estudiar\u00e1 Gan\u00edmedes en detalle y tambi\u00e9n realizar\u00e1 observaciones de Europa y Calisto durante su misi\u00f3n."}, {"question": "\u00bfQu\u00e9 resulta especialmente interesante de las lunas heladas de J\u00fapiter?", "answers": ["Algunas pueden contener oc\u00e9anos subsuperficiales", "Todas tienen la atm\u00f3sfera de la Tierra", "Son m\u00e1s calientes que el Sol", "Est\u00e1n hechas completamente de metal"], "correct": 0, "fact": "Las pruebas indican que algunas de las lunas heladas de J\u00fapiter contienen oc\u00e9anos bajo sus superficies congeladas."}, {"question": "\u00bfQu\u00e9 luna est\u00e1 prevista como objetivo principal de la misi\u00f3n orbital de JUICE?", "answers": ["Gan\u00edmedes", "\u00cdo", "Europa", "Amaltea"], "correct": 0, "fact": "Est\u00e1 previsto que JUICE entre en \u00f3rbita alrededor de Gan\u00edmedes, convirti\u00e9ndose en la primera nave espacial en orbitar una luna distinta de la Luna de la Tierra."}, {"question": "\u00bfPor qu\u00e9 son interesantes las lunas heladas en la b\u00fasqueda de entornos potencialmente habitables?", "answers": ["Pueden tener agua l\u00edquida bajo el hielo", "Todas est\u00e1n cerca del Sol", "Tienen los continentes de la Tierra", "Est\u00e1n hechas de ox\u00edgeno puro"], "correct": 0, "fact": "El agua l\u00edquida es uno de los ingredientes que los cient\u00edficos consideran importantes al estudiar entornos que podr\u00edan albergar alguna forma de vida."}], "\u20ac44,000": [{"question": "\u00bfQu\u00e9 misi\u00f3n de la ESA y JAXA utiliza una compleja serie de sobrevuelos planetarios en su viaje a Mercurio?", "answers": ["Euclid", "Sentinel-2", "BepiColombo", "Philae"], "correct": 2, "fact": "Llegar a Mercurio es sorprendentemente dif\u00edcil. Una nave espacial debe perder una gran cantidad de energ\u00eda orbital, por lo que BepiColombo utiliza sobrevuelos como maniobras de guiado c\u00f3smico cuidadosamente planificadas."}, {"question": "\u00bfQu\u00e9 planeta es el destino principal de BepiColombo?", "answers": ["Mercurio", "Marte", "J\u00fapiter", "Venus"], "correct": 0, "fact": "BepiColombo es una misi\u00f3n conjunta de la ESA y JAXA dise\u00f1ada para estudiar Mercurio, el planeta m\u00e1s interior del Sistema Solar."}, {"question": "\u00bfPor qu\u00e9 es especialmente dif\u00edcil llegar a Mercurio para una nave espacial procedente de la Tierra?", "answers": ["Debe perder energ\u00eda orbital para acercarse al Sol", "Mercurio tiene una atm\u00f3sfera espesa", "Mercurio est\u00e1 fuera del Sistema Solar", "Tiene oc\u00e9anos que bloquean las naves espaciales"], "correct": 0, "fact": "Una nave espacial que viaja desde la Tierra tiene que perder una cantidad considerable de energ\u00eda orbital para entrar en una \u00f3rbita cercana al Sol, lo que convierte a Mercurio en un destino exigente."}, {"question": "\u00bfCu\u00e1ndo se fund\u00f3 la ESA?", "answers": ["1975", "1965", "1970", "1985"], "correct": 0, "fact": "JAXA es la agencia espacial nacional y organizaci\u00f3n de investigaci\u00f3n de Jap\u00f3n. BepiColombo es una colaboraci\u00f3n entre JAXA y la ESA."}, {"question": "\u00bfD\u00f3nde se encuentra la sede de la ESA?", "answers": ["Par\u00eds, Francia", "Berl\u00edn, Alemania", "Roma, Italia", "Londres, Reino Unido"], "correct": 0, "fact": "La ESA cuenta con 23 Estados miembros y siete instalaciones principales en Europa, y su sede se encuentra en el centro de Par\u00eds."}, {"question": "\u00bfCu\u00e1l es la instalaci\u00f3n m\u00e1s grande de la ESA?", "answers": ["ESRIN, Italia", "ESTEC, Pa\u00edses Bajos", "ESOC, Alemania", "Sede de la ESA, Francia"], "correct": 1, "fact": "ESTEC es el Centro Europeo de Investigaci\u00f3n y Tecnolog\u00eda Espaciales, el coraz\u00f3n t\u00e9cnico de la ESA, donde nacen la mayor\u00eda de los proyectos de la ESA y donde se gu\u00edan a trav\u00e9s de las distintas fases de desarrollo."}]}}

# The quiz still has one question per prize level, but the question for each
# level is selected randomly when a new game starts.
PRIZE_LADDER = list(LOCALIZED_QUESTION_BANKS['en'].keys())
LADDER_LENGHT = len(PRIZE_LADDER)
LETTERS = ("A", "B", "C", "D")

# Validate the question bank when the program starts.
for language in LOCALIZED_QUESTION_BANKS.keys():
    QUESTION_BANK=LOCALIZED_QUESTION_BANKS[language]
    for prize_value, questions in QUESTION_BANK.items():
        if not questions:
            raise ValueError(f"No questions configured for {prize_value}")
        for question in questions:
            if len(question["answers"]) != 4:
                raise ValueError(f"{prize_value}: every question must have exactly 4 answers")
            if not 0 <= question["correct"] < 4:
                raise ValueError(f"{prize_value}: correct answer must be 0, 1, 2 or 3")

class ESASpaceQuiz(tk.Tk):
    BG = "#030515"
    PANEL = "#090d2c"
    BLUE = "#163c8c"
    BRIGHT_BLUE = "#2474ff"
    CYAN = "#49d9ff"
    GOLD = "#ffc94a"
    ORANGE = "#ff8b27"
    WHITE = "#f7fbff"
    MUTED = "#9eb4d6"
    GREEN = "#1fbd72"
    RED = "#d9445e"

    def __init__(self):
        super().__init__()
        self.title("ESA Space Challenge")
        self.geometry("1280x800")
        self.minsize(960, 650)
        self.configure(bg=self.BG)
        self.fullscreen = False
        self.language = "en"
        self.last_answer_correct = False
        self.current = 0
        self.selected_questions = []
        self.score = 0
        self.correct_count = 0
        self.locked = False
        self.after_id = None

        self.bind("<F11>", self.toggle_fullscreen)
        self.bind("<Escape>", self.leave_fullscreen)
        self.bind("<Key-r>", lambda _e: self.restart())
        self.bind("<Key-R>", lambda _e: self.restart())
        self.bind("<Configure>", self.on_resize)

        self.canvas = tk.Canvas(self, bg=self.BG, highlightthickness=0)
        self.canvas.pack(fill="both", expand=True)
        self.draw_background()
        self.show_start_screen()

    def t(self, key, **kwargs):
        text = UI_TEXT[self.language].get(key, UI_TEXT["en"][key])
        return text.format(**kwargs) if kwargs else text

    def set_language(self, language):
        self.language = language
        self.title("ESA Space Challenge")
        self.show_start_screen()

    def toggle_fullscreen(self, _event=None):
        self.fullscreen = not self.fullscreen
        self.attributes("-fullscreen", self.fullscreen)

    def leave_fullscreen(self, _event=None):
        self.fullscreen = False
        self.attributes("-fullscreen", False)

    def on_resize(self, event):
        if event.widget is self:
            if self.after_id:
                self.after_cancel(self.after_id)
            self.after_id = self.after(80, self.redraw_current_screen)

    def clear(self):
        self.canvas.delete("all")

    def draw_background(self):
        w = max(self.winfo_width(), 960)
        h = max(self.winfo_height(), 650)
        self.canvas.create_rectangle(0, 0, w, h, fill=self.BG, outline="")

        # Game-show inspired radial rings and light beams, drawn without external assets.
        cx, cy = int(w * 0.39), int(h * 0.43)
        for radius, colour, width in [
            (int(h * 0.48), "#08164a", 3),
            (int(h * 0.38), "#0d2870", 2),
            (int(h * 0.29), "#1450a4", 2),
            (int(h * 0.21), "#2474ff", 2),
        ]:
            self.canvas.create_oval(cx-radius, cy-radius, cx+radius, cy+radius,
                                    outline=colour, width=width)

        for angle in range(0, 360, 20):
            r1, r2 = int(h * 0.10), int(h * 0.50)
            x1 = cx + math.cos(math.radians(angle)) * r1
            y1 = cy + math.sin(math.radians(angle)) * r1
            x2 = cx + math.cos(math.radians(angle)) * r2
            y2 = cy + math.sin(math.radians(angle)) * r2
            self.canvas.create_line(x1, y1, x2, y2, fill="#0a245f", width=1)

        # Stars
        star_points = [
            (.05,.10),(.12,.28),(.20,.08),(.28,.20),(.35,.06),(.45,.13),
            (.53,.05),(.61,.18),(.70,.09),(.78,.23),(.88,.11),(.95,.30),
            (.08,.72),(.18,.88),(.31,.76),(.47,.91),(.58,.74),(.69,.88),
            (.81,.69),(.91,.86),(.97,.62),(.55,.31),(.24,.55),(.42,.67)
        ]
        for i, (sx, sy) in enumerate(star_points):
            r = 1 + (i % 3 == 0)
            self.canvas.create_oval(w*sx-r, h*sy-r, w*sx+r, h*sy+r,
                                    fill=self.WHITE, outline="")

    def rounded_rect(self, x1, y1, x2, y2, radius=20, **kwargs):
        points = [
            x1+radius,y1, x2-radius,y1, x2,y1, x2,y1+radius,
            x2,y2-radius, x2,y2, x2-radius,y2, x1+radius,y2,
            x1,y2, x1,y2-radius, x1,y1+radius, x1,y1
        ]
        return self.canvas.create_polygon(points, smooth=True, **kwargs)

    def text_button(self, x1, y1, x2, y2, text, command,
                    fill=None, outline=None, font_size=18, tag=None):
        tag = tag or f"button_{x1}_{y1}"
        fill = fill or self.BLUE
        outline = outline or self.CYAN
        self.rounded_rect(x1, y1, x2, y2, radius=18, fill=fill,
                          outline=outline, width=2, tags=(tag,))
        self.canvas.create_text((x1+x2)/2, (y1+y2)/2, text=text,
                                fill=self.WHITE, font=("Arial", font_size, "bold"),
                                width=max(100, x2-x1-30), justify="center", tags=(tag,))
        self.canvas.tag_bind(tag, "<Button-1>", lambda _e: command())
        self.canvas.tag_bind(tag, "<Enter>", lambda _e: self.set_button_colour(tag, self.BRIGHT_BLUE))
        self.canvas.tag_bind(tag, "<Leave>", lambda _e: self.set_button_colour(tag, fill))
        return tag

    def set_button_colour(self, tag, colour):
        items = self.canvas.find_withtag(tag)
        if items:
            self.canvas.itemconfigure(items[0], fill=colour)

    def show_start_screen(self):
        self.screen = "start"
        self.clear()
        self.draw_background()
        w, h = self.winfo_width(), self.winfo_height()
        cx = w * 0.42

        self.canvas.create_text(cx, h*0.16, text="ESA", fill=self.CYAN,
                                font=("Arial", max(24, int(h*.055)), "bold"))
        self.canvas.create_text(cx, h*0.24, text="SPACE CHALLENGE", fill=self.WHITE,
                                font=("Arial", max(28, int(h*.065)), "bold"))
        self.canvas.create_text(cx, h*0.33,
                                text=self.t("subtitle"),
                                fill=self.MUTED, font=("Arial", max(14, int(h*.026))),
                                width=w*.66, justify="center")

        r = min(w, h) * .15
        self.canvas.create_oval(cx-r, h*.49-r, cx+r, h*.49+r,
                                fill="#07113a", outline=self.CYAN, width=4)
        self.canvas.create_oval(cx-r*.76, h*.49-r*.76, cx+r*.76, h*.49+r*.76,
                                outline=self.GOLD, width=3)
        self.canvas.create_text(cx, h*.465, text=str(LADDER_LENGHT), fill=self.WHITE,
                                font=("Arial", max(30, int(h*.075)), "bold"))
        self.canvas.create_text(cx, h*.545, text=f"{LADDER_LENGHT} {self.t('questions')}", fill=self.GOLD,
                                font=("Arial", max(14, int(h*.025)), "bold"))

        self.text_button(cx-w*.13, h*.72, cx+w*.13, h*.81,
                         self.t("start"), self.start_quiz,
                         fill="#123d8b", outline=self.GOLD,
                         font_size=max(15, int(h*.026)), tag="start")
        self.canvas.create_text(cx, h*.89,
                                text=self.t("controls"),
                                fill=self.MUTED, font=("Arial", max(10, int(h*.017))))
        # Language selector. Changing language redraws this screen immediately.
        self.canvas.create_text(cx, h*.065, text=self.t("choose"), fill=self.MUTED,
                                font=("Arial", max(10, int(h*.017)), "bold"))
        labels = [("en", "EN"), ("it", "IT"), ("de", "DE"), ("fr", "FR"), ("es", "ES")]
        bw, gap = w*.052, w*.008
        total_w = len(labels)*bw + (len(labels)-1)*gap
        lx = cx-total_w/2
        for i, (code, label) in enumerate(labels):
            x1 = lx+i*(bw+gap)
            self.text_button(x1, h*.085, x1+bw, h*.13, label,
                             lambda c=code: self.set_language(c),
                             fill=self.BRIGHT_BLUE if code == self.language else "#101c45",
                             outline=self.GOLD if code == self.language else self.CYAN,
                             font_size=max(9, int(h*.015)), tag=f"lang_{code}")
        self.draw_ladder(w, h, active=None)

    def randomize_answers(self, question):
        indexed_answers = list(enumerate(question["answers"]))
        random.shuffle(indexed_answers)
        original_correct = question["correct"]
        question["answers"] = [answer for _, answer in indexed_answers]
        question["correct"] = next(
            i for i, (orig_idx, _) in enumerate(indexed_answers)
            if orig_idx == original_correct
        )
        return question

    def start_quiz(self):
        self.current = 0
        self.score = 0
        self.correct_count = 0
        self.locked = False

        # Pick exactly one question at random for each prize level.
        # Shift the answers so it is not always the same correct answer placement.
        # The selected questions remain fixed for the whole game.
        self.selected_questions = [
            self.randomize_answers(__import__("copy").deepcopy(random.choice(LOCALIZED_QUESTION_BANKS[self.language][value])))
            for value in PRIZE_LADDER
        ]

        self.show_question()

    def draw_ladder(self, w, h, active=None):
        x1, x2 = w*.80, w*.97
        y1, y2 = h*.10, h*.90
        self.rounded_rect(x1, y1, x2, y2, 22, fill="#060a22",
                          outline="#2359bd", width=2)
        self.canvas.create_text((x1+x2)/2, y1+h*.045, text=self.t("ladder"),
                                fill=self.CYAN, font=("Arial", max(11, int(h*.019)), "bold"))
        usable = y2-y1-h*.10
        step = usable/LADDER_LENGHT
        for display_i, value in enumerate(reversed(PRIZE_LADDER)):
            question_i = LADDER_LENGHT-1-display_i
            y = y1+h*.085 + display_i*step + step/2
            is_active = active == question_i
            is_passed = active is not None and question_i < active
            if is_active:
                self.rounded_rect(x1+8, y-step*.39, x2-8, y+step*.39, 10,
                                  fill=self.ORANGE, outline=self.GOLD, width=2)
                colour = self.WHITE
            elif is_passed:
                colour = self.GOLD
            else:
                colour = self.MUTED
            self.canvas.create_text(x1+18, y, text=str(question_i+1), anchor="w",
                                    fill=colour, font=("Arial", max(9, int(h*.016)), "bold"))
            self.canvas.create_text(x2-16, y, text=value, anchor="e",
                                    fill=colour, font=("Arial", max(9, int(h*.016)), "bold"))

    def show_question(self):
        self.screen = "question"
        self.locked = False
        self.clear()
        self.draw_background()
        w, h = self.winfo_width(), self.winfo_height()
        q = self.selected_questions[self.current]
        main_right = w*.76

        self.canvas.create_text(w*.03, h*.045, anchor="w",
                                text="ESA SPACE CHALLENGE", fill=self.CYAN,
                                font=("Arial", max(14, int(h*.025)), "bold"))
        self.canvas.create_text(main_right-w*.02, h*.045, anchor="e",
                                text=self.t("question", n=self.current+1, total=LADDER_LENGHT, prize=PRIZE_LADDER[self.current]),
                                fill=self.GOLD, font=("Arial", max(12, int(h*.021)), "bold"))

        # Progress bar
        px1, px2, py = w*.04, main_right-w*.03, h*.09
        self.canvas.create_rectangle(px1, py, px2, py+8, fill="#101c45", outline="")
        self.canvas.create_rectangle(px1, py, px1+(px2-px1)*(self.current+1)/LADDER_LENGHT,
                                     py+8, fill=self.CYAN, outline="")

        self.rounded_rect(w*.04, h*.15, main_right-w*.03, h*.38, 26,
                          fill="#07113a", outline=self.CYAN, width=3)
        self.canvas.create_text((w*.04+main_right-w*.03)/2, h*.265,
                                text=q["question"], fill=self.WHITE,
                                font=("Arial", max(18, int(h*.036)), "bold"),
                                width=main_right-w*.13, justify="center")

        coords = [
            (w*.04, h*.44, w*.38, h*.59),
            (w*.405, h*.44, main_right-w*.03, h*.59),
            (w*.04, h*.63, w*.38, h*.78),
            (w*.405, h*.63, main_right-w*.03, h*.78),
        ]
        for idx, ((x1,y1,x2,y2), answer) in enumerate(zip(coords, q["answers"])):
            tag = f"answer_{idx}"
            self.rounded_rect(x1,y1,x2,y2,20, fill=self.PANEL,
                              outline=self.BRIGHT_BLUE, width=2, tags=(tag,))
            self.canvas.create_text(x1+28, (y1+y2)/2, text=LETTERS[idx]+":",
                                    anchor="w", fill=self.GOLD,
                                    font=("Arial", max(15, int(h*.027)), "bold"), tags=(tag,))
            self.canvas.create_text(x1+70, (y1+y2)/2, text=answer,
                                    anchor="w", fill=self.WHITE,
                                    font=("Arial", max(12, int(h*.021)), "bold"),
                                    width=x2-x1-90, justify="left", tags=(tag,))
            self.canvas.tag_bind(tag, "<Button-1>", lambda _e, i=idx: self.choose_answer(i))
            self.canvas.tag_bind(tag, "<Enter>", lambda _e, t=tag: self.set_answer_colour(t, self.BLUE))
            self.canvas.tag_bind(tag, "<Leave>", lambda _e, t=tag: self.set_answer_colour(t, self.PANEL))

        self.canvas.create_text(w*.04, h*.87, anchor="w",
                                text=self.t("correct_answers", correct=self.correct_count, score=self.print_score()),
                                fill=self.MUTED, font=("Arial", max(11, int(h*.019)), "bold"))
        self.draw_ladder(w, h, active=self.current)

    def set_answer_colour(self, tag, colour):
        if self.locked:
            return
        items = self.canvas.find_withtag(tag)
        if items:
            self.canvas.itemconfigure(items[0], fill=colour)

    def choose_answer(self, selected):
        if self.locked:
            return
        self.locked = True
        q = self.selected_questions[self.current]
        correct = q["correct"]
        is_correct = selected == correct

        for i in range(4):
            items = self.canvas.find_withtag(f"answer_{i}")
            if not items:
                continue
            if i == correct:
                self.canvas.itemconfigure(items[0], fill=self.GREEN, outline="#86ffc1", width=3)
            elif i == selected:
                self.canvas.itemconfigure(items[0], fill=self.RED, outline="#ff9aaa", width=3)
            else:
                self.canvas.itemconfigure(items[0], fill="#0b1029", outline="#263157")

        if is_correct:
            self.correct_count += 1
            self.score = self.score + int(PRIZE_LADDER[self.current][1:].replace(',',''))

        self.last_answer_correct = is_correct
        self.after(850, lambda: self.show_fact(is_correct))

    def show_fact(self, is_correct):
        self.screen = "fact"
        self.clear()
        self.draw_background()
        w, h = self.winfo_width(), self.winfo_height()
        q = self.selected_questions[self.current]
        main_right = w*.76
        colour = self.GREEN if is_correct else self.RED
        headline = self.t("correct") if is_correct else self.t("wrong")

        self.canvas.create_text((main_right)/2, h*.15, text=headline,
                                fill=colour, font=("Arial", max(30, int(h*.065)), "bold"))
        self.canvas.create_text(main_right/2, h*.25,
                                text=self.t("answer_is", letter=LETTERS[q['correct']], answer=q['answers'][q['correct']]),
                                fill=self.WHITE, font=("Arial", max(16, int(h*.031)), "bold"),
                                width=main_right-w*.12, justify="center")

        self.rounded_rect(w*.07, h*.36, main_right-w*.05, h*.66, 28,
                          fill="#08133b", outline=self.GOLD, width=3)
        self.canvas.create_text(w*.11, h*.42, anchor="w", text=self.t("fun_fact"),
                                fill=self.GOLD, font=("Arial", max(14, int(h*.025)), "bold"))
        self.canvas.create_text((w*.07+main_right-w*.05)/2, h*.525,
                                text=q["fact"], fill=self.WHITE,
                                font=("Arial", max(14, int(h*.026))),
                                width=main_right-w*.20, justify="center")

        button_text = self.t("final") if self.current == LADDER_LENGHT-1 else self.t("next")
        self.text_button(main_right/2-w*.12, h*.73, main_right/2+w*.12, h*.82,
                         button_text, self.next_question,
                         fill="#123d8b", outline=self.GOLD,
                         font_size=max(14, int(h*.023)), tag="next")
        self.draw_ladder(w, h, active=self.current)

    def next_question(self):
        if self.current < LADDER_LENGHT-1:
            self.current += 1
            self.show_question()
        else:
            self.show_results()

    def result_title(self):
        titles = {
            "en": [("ESA MISSION DIRECTOR", "A perfect flight through the quiz!"), ("COSMIC EXPERT", "The universe clearly has your attention."), ("ASTRONAUT IN TRAINING", "A strong result and a great launchpad for more discovery."), ("SPACE EXPLORER", "You are well on your way across the Solar System."), ("EARTH OBSERVER", "Every space journey begins by looking up and asking questions.")],
            "it": [("DIRETTORE DI MISSIONE ESA", "Un volo perfetto attraverso il quiz!"), ("ESPERTO COSMICO", "L’universo ha chiaramente la tua attenzione."), ("ASTRONAUTA IN ADDESTRAMENTO", "Un ottimo risultato e una splendida base per nuove scoperte."), ("ESPLORATORE SPAZIALE", "Sei sulla buona strada attraverso il Sistema Solare."), ("OSSERVATORE DELLA TERRA", "Ogni viaggio spaziale inizia guardando in alto e ponendo domande.")],
            "de": [("ESA-MISSIONSDIREKTOR", "Ein perfekter Flug durch das Quiz!"), ("KOSMISCHER EXPERTE", "Das Universum hat eindeutig deine Aufmerksamkeit."), ("ASTRONAUT IM TRAINING", "Ein starkes Ergebnis und eine gute Startrampe für weitere Entdeckungen."), ("WELTRAUMFORSCHER", "Du bist auf einem guten Weg durch das Sonnensystem."), ("ERDBEOBACHTER", "Jede Raumfahrt beginnt mit einem Blick nach oben und mit Fragen.")],
            "fr": [("DIRECTEUR DE MISSION ESA", "Un parcours parfait dans le quiz !"), ("EXPERT COSMIQUE", "L’Univers a clairement toute votre attention."), ("ASTRONAUTE EN FORMATION", "Un excellent résultat et une belle rampe de lancement vers de nouvelles découvertes."), ("EXPLORATEUR SPATIAL", "Vous êtes en bonne voie à travers le Système solaire."), ("OBSERVATEUR DE LA TERRE", "Tout voyage spatial commence en levant les yeux et en posant des questions.")],
            "es": [("DIRECTOR DE MISIÓN DE LA ESA", "¡Un vuelo perfecto a través del concurso!"), ("EXPERTO CÓSMICO", "Está claro que el universo tiene toda tu atención."), ("ASTRONAUTA EN FORMACIÓN", "Un gran resultado y una excelente plataforma para nuevos descubrimientos."), ("EXPLORADOR ESPACIAL", "Vas por buen camino a través del Sistema Solar."), ("OBSERVADOR DE LA TIERRA", "Todo viaje espacial comienza mirando hacia arriba y haciendo preguntas.")]
        }
        if self.correct_count == LADDER_LENGHT: idx = 0
        elif self.correct_count >= 8: idx = 1
        elif self.correct_count >= 6: idx = 2
        elif self.correct_count >= 4: idx = 3
        else: idx = 4
        return titles[self.language][idx]

    def print_score(self):
        return f'€{self.score:,}'
        
    def show_results(self):
        self.screen = "results"
        self.clear()
        self.draw_background()
        w, h = self.winfo_width(), self.winfo_height()
        title, subtitle = self.result_title()
        earned = self.print_score()
        cx = w*.50

        self.canvas.create_text(cx, h*.12, text=self.t("complete"),
                                fill=self.CYAN, font=("Arial", max(22, int(h*.045)), "bold"))
        self.canvas.create_text(cx, h*.22, text=title,
                                fill=self.GOLD, font=("Arial", max(26, int(h*.058)), "bold"))
        self.canvas.create_text(cx, h*.29, text=subtitle,
                                fill=self.MUTED, font=("Arial", max(13, int(h*.024))),
                                width=w*.75, justify="center")

        self.rounded_rect(w*.20, h*.36, w*.80, h*.64, 30,
                          fill="#07113a", outline=self.CYAN, width=3)
        self.canvas.create_text(w*.35, h*.46, text=f"{self.correct_count}/{LADDER_LENGHT}",
                                fill=self.WHITE, font=("Arial", max(32, int(h*.075)), "bold"))
        self.canvas.create_text(w*.35, h*.56, text=self.t("correct_label"),
                                fill=self.MUTED, font=("Arial", max(12, int(h*.021)), "bold"))
        self.canvas.create_line(w*.50, h*.40, w*.50, h*.60, fill="#2850a0", width=2)
        self.canvas.create_text(w*.65, h*.46, text=earned,
                                fill=self.GOLD, font=("Arial", max(32, int(h*.075)), "bold"))
        self.canvas.create_text(w*.65, h*.56, text=self.t("score_label"),
                                fill=self.MUTED, font=("Arial", max(12, int(h*.021)), "bold"))

        self.text_button(w*.31, h*.71, w*.49, h*.81, self.t("again"), self.restart,
                         fill="#123d8b", outline=self.GOLD,
                         font_size=max(14, int(h*.024)), tag="again")
        self.text_button(w*.52, h*.71, w*.70, h*.81, self.t("exit"), self.destroy,
                         fill="#24144d", outline=self.CYAN,
                         font_size=max(14, int(h*.024)), tag="exit")
        self.canvas.create_text(cx, h*.89,
                                text=self.t("thanks"),
                                fill=self.WHITE, font=("Arial", max(12, int(h*.022)), "bold"))

    def restart(self):
        self.current = 0
        self.selected_questions = []
        self.score = 0
        self.correct_count = 0
        self.locked = False
        self.show_start_screen()

    def redraw_current_screen(self):
        self.after_id = None
        screen = getattr(self, "screen", "start")
        if screen == "start":
            self.show_start_screen()
        elif screen == "question":
            self.show_question()
        elif screen == "fact":
            # Preserve the most recent answer state approximately when resizing.
            self.show_fact(self.last_answer_correct)
        elif screen == "results":
            self.show_results()


if __name__ == "__main__":
    app = ESASpaceQuiz()
    app.mainloop()
